/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:({
  'ohp':'Oxford Learner’s Dictionaries: https://www.oxfordlearnersdictionaries.com/us/definition/english/ohp',
  'Oceania':'Etymonline: https://www.etymonline.com/word/oceania',
  'occur to':'Etymonline: https://www.etymonline.com/word/occur; https://www.etymonline.com/word/to',
  'odd one out':'Etymonline: https://www.etymonline.com/word/odd; https://www.etymonline.com/word/one; https://www.etymonline.com/word/out',
  'of course':'Etymonline: https://www.etymonline.com/word/of; https://www.etymonline.com/word/course',
  'of late':'Etymonline: https://www.etymonline.com/word/of; https://www.etymonline.com/word/late',
  'of one mind':'Etymonline: https://www.etymonline.com/word/of; https://www.etymonline.com/word/one; https://www.etymonline.com/word/mind',
  'of that kind':'Etymonline: https://www.etymonline.com/word/of; https://www.etymonline.com/word/that; https://www.etymonline.com/word/kind',
  'of which':'Etymonline: https://www.etymonline.com/word/of; https://www.etymonline.com/word/which',
  'of whom':'Etymonline: https://www.etymonline.com/word/of; https://www.etymonline.com/word/whom',
  'off target':'Etymonline: https://www.etymonline.com/word/off; https://www.etymonline.com/word/target',
  'off-campus':'Etymonline: https://www.etymonline.com/word/off; https://www.etymonline.com/word/campus',
  'off-limits':'Etymonline: https://www.etymonline.com/word/off; https://www.etymonline.com/word/limit',
  'old hand':'Etymonline: https://www.etymonline.com/word/old; https://www.etymonline.com/word/hand',
  'old-fashioned':'Etymonline: https://www.etymonline.com/word/old; https://www.etymonline.com/word/fashion',
  'OK':'Etymonline: https://www.etymonline.com/word/OK'
}[w]||('Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')))});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('occultation','From occult + -ation, naming the event in which one celestial body is hidden from view by another.',C('occultation.s1','天文学','The observatory scheduled the occultation observation for dawn, when the Moon would pass in front of the bright star.','天文台把掩星观测安排在黎明时分，那时月亮将从亮星前方经过。','The observatory scheduled the occultation observation / for dawn / when the Moon would pass in front of the bright star.','occultation 指一个天体从视线中被另一个天体遮住的事件。','月亮经过恒星前方，造成短暂遮蔽。'),M('The report called the star’s disappearance an occultation even though no foreground body crossed the line of sight.','The report called the star’s disappearance an occultation because the Moon crossed the line of sight.','掩星需要前景天体遮挡后方天体，单纯变暗不够。','distinction'),[Q(1,'What caused the star to disappear from view?','The Moon passed in front of it.','The star moved behind a cloud inside the observatory.','The telescope changed the star into a planet.','occultation.s1 指天体互相遮挡造成的视线中断。'),Q(1,'Which event is an occultation?','A planet hides a distant star from an observer.','A star grows brighter at sunrise.','A telescope records an empty sky.','一个天体遮住另一个天体才是掩星。','context'),Q(1,'What was the observatory planning to observe?','A celestial body crossing another body’s apparent path.','An ordinary sunrise with no celestial alignment.','A star’s chemical composition only.','例句的观测对象是月亮遮住恒星的过程。'),Q(1,'Why is occultation more precise than darkness here?','It names an astronomical hiding event caused by another body.','It means the telescope was switched off.','It describes any night with no moon.','occultation 是天文学中的遮掩事件术语。','distinction')]);
P('occupancy','From occupant and occupy, with the noun-forming suffix -ancy; it denotes being occupied and, in buildings, the rate of use.',C('occupancy.s1','商业','The hotel’s occupancy reached 92 percent during the festival, so the manager opened two extra floors.','节日期间酒店入住率达到92%，因此经理又开放了两层客房。','The hotel’s occupancy reached 92 percent / during the festival / so the manager opened two extra floors.','occupancy 可指房间有人使用的状态，也可指入住率。','百分数表示已入住客房占总量的比例。'),M('The hotel reported 92 percent occupancy while every room was empty.','The hotel reported 0 percent occupancy while every room was empty.','occupancy rate 表示实际使用比例；房间全空时不能是92%。','measurement'),[Q(1,'What did the hotel’s 92 percent occupancy measure?','The share of rooms in use.','The number of floors under construction.','The percentage of guests who work at the hotel.','occupancy.s1 可指入住率，即房间被使用的比例。'),Q(1,'Why did the manager open extra floors?','Demand was high during the festival.','The hotel had no guests.','The building was being demolished.','高入住率说明客房需求旺盛。'),Q(1,'A building’s occupancy concerns whether it is?','being used or inhabited','painted a certain color','owned by one person only','occupancy 表示使用或居住状态。','meaning'),Q(1,'Which report uses occupancy correctly?','The auditorium was at 70% occupancy with most seats filled.','The empty auditorium had 100% occupancy.','The occupancy listed the singer’s favorite song.','入座比例是 occupancy 的恰当用法。','context')]);
P('occupant','From Latin occupare “take possession of,” via occupy + agent-forming -ant; an occupant is a person living in or using a place or vehicle.',C('occupant.s1','社会','Each occupant of the minibus was asked to fasten a seat belt before the driver started the engine.','司机启动发动机前，要求小巴里的每位乘员系好安全带。','Each occupant of the minibus / was asked to fasten a seat belt / before the driver started the engine.','occupant 指住在某处或使用某辆车的人。','乘员占用车辆座位，因此是车辆的 occupant。'),M('The safety form listed the empty seat as an occupant and left the actual passenger unnamed.','The safety form listed the passenger sitting in the seat as an occupant.','occupant 是人，不是被占用的座位。','word-choice'),[Q(1,'Who counted as an occupant of the minibus?','A person riding in it.','The empty seat itself.','The engine oil.','occupant 指使用车辆的人。'),Q(1,'What was each occupant asked to do?','Fasten a seat belt.','Start a second engine.','Leave the vehicle moving.','例句要求每名乘员系好安全带。'),Q(1,'Who is an occupant of a house?','Someone currently living there.','A person designing a distant house.','A map seller outside.','居住者是房屋的 occupant。'),Q(1,'Why is “the seat is an occupant” incorrect?','An occupant is a person who lives in or uses a place.','Occupant means a fuel tank.','A seat can only be called a driver.','该词指人，不指座椅。','word-choice')]);
P('occupation','From Latin occupatio “seizure, occupation,” from occupare “take possession”; English senses include a job, time-filling activity, and military control of a place.',[C('occupation.s1','工作','Her occupation is marine engineer, a job that takes her from the design office to research vessels.','她的职业是海洋工程师，这份工作让她在设计办公室和科考船之间奔忙。','Her occupation is marine engineer / a job that takes her / from the design office / to research vessels.','occupation.s1 指职业或日常工作。','海洋工程师是她的职业。'),C('occupation.s2','通用','Gardening became his favorite occupation after retirement, although he never earned money from it.','退休后园艺成了他最喜欢的消遣，尽管他从未靠此赚钱。','Gardening became his favorite occupation / after retirement / although he never earned money from it.','occupation.s2 指打发时间的活动，不一定有报酬。','园艺是休闲活动而非谋生工作。'),C('occupation.s3','历史','The museum documents the occupation of the port city and the restrictions imposed by the foreign army.','博物馆记录了港口城市遭占领的历史，以及外国军队施加的限制。','The museum documents the occupation of the port city / and the restrictions / imposed by the foreign army.','occupation.s3 指军队控制某地的占领行动或状态。','外国军队控制港口城市构成军事占领。')],M('The museum described the occupation as a relaxing hobby the foreign army pursued in its free time.','The museum described the occupation as the foreign army’s control of the port city.','军队控制城市是军事占领，不是消遣。','distinction'),[Q(1,'What is the engineer’s occupation?','Marine engineer.','A port city under military control.','An unpaid gardening hobby.','occupation.s1 指职业。'),Q(2,'Why is gardening an occupation after retirement?','It fills his time as an activity.','It is his paid engineering job.','It is an army’s control of a city.','occupation.s2 不要求有报酬。'),Q(3,'What did the foreign army do to the port city?','It took control of it.','It hired the museum staff.','It planted a garden.','occupation.s3 是军事占领。'),Q(1,'Which sentence uses occupation to mean a job?','Her occupation is teaching biology.','The occupation ended when the army withdrew.','Woodworking is his weekend occupation.','teaching biology 是谋生职业。','distinction')]);
P('occupational','From occupation + -al, the adjective describing something connected with a job or profession.',C('occupational.s1','健康','The clinic offered an occupational health check for workers who handled solvents every day.','诊所为每天接触溶剂的工人提供职业健康检查。','The clinic offered an occupational health check / for workers / who handled solvents every day.','occupational 表示与职业、工作环境或工作活动有关。','检查针对工作中的化学品接触风险。','word-formation'),M('The clinic called a family picnic an occupational health check although it assessed no work-related risk.','The clinic called the solvent-exposure screening an occupational health check.','occupational health 关注工作相关的健康风险，不是普通野餐。','word-choice'),[Q(1,'Why were the workers offered the check?','Their jobs involved daily solvent handling.','They were choosing a picnic location.','They applied for a driving license.','occupational.s1 指工作相关的健康检查。'),Q(1,'Which phrase naturally uses occupational?','occupational safety','occupational sunrise','occupational flavor of soup','occupational 常修饰 safety、health 等工作相关名词。','collocation'),Q(1,'What does -al contribute in occupational?','It forms an adjective meaning related to occupation.','It marks a plural noun.','It marks a past-tense verb.','occupation + -al 构成形容词。','word-formation'),Q(1,'An occupational hazard is a risk connected with?','a person’s work','a holiday film','the weather at home','occupational 表示与工作有关。','meaning')]);
P('occupationally','From occupational + -ly, formed from occupation + -al; it means with regard to a person’s job or profession.',C('occupationally.s1','工作','The two nurses were occupationally similar, but one worked in a clinic and the other in a school.','两名护士的职业性质相似，但一人在诊所工作，另一人在学校工作。','The two nurses were occupationally similar / but one worked in a clinic / and the other in a school.','occupationally 表示“就职业而言”，修饰职业方面的相似或不同。','副词说明相似性限于工作领域。','word-formation'),M('The report said the nurses were occupationally similar because they both liked the same music at home.','The report said the nurses were occupationally similar because both worked as nurses.','occupationally 关乎职业，不是私人音乐喜好。','context'),[Q(1,'In what respect were the nurses similar?','Their professions.','Their home addresses.','Their favorite songs.','occupationally 表示就职业而言。'),Q(1,'What does occupationally modify in the example?','The kind of similarity between the nurses.','The location of the music.','The number of patients.','副词限定“相似”发生在职业方面。'),Q(1,'Which phrase has the same occupational focus?','occupationally related duties','occupationally delicious soup','occupationally blue sky','occupationally relates to work or profession.','word-choice'),Q(1,'How is occupationally formed?','occupational + -ly','occupy + past-tense -ed','occupation + plural -s','-ly forms an adverb from occupational.','word-formation')]);
P('occupied','Past participle of occupy, from Latin occupare “take possession”; as an adjective it describes a place in use or a person busy.',C('occupied.s1','通用','The conference room was occupied until noon, so the team moved its planning session to the library.','会议室到中午前一直有人使用，因此团队把计划会议改到图书馆。','The conference room was occupied / until noon / so the team moved its planning session / to the library.','occupied 可表示房间正被使用，也可表示人正忙。','房间被预订使用，所以团队另找地点。'),M('The sign said the room was occupied while it was locked, empty, and available for anyone to use.','The sign said the room was unoccupied while it was empty and available.','occupied 表示正在使用或被占用，与空置相反。'),[Q(1,'Why did the team move its meeting?','The conference room was in use.','The library was occupied by the meeting.','The team had finished its plan.','occupied.s1 表示会议室当时有人使用。'),Q(1,'Which sign indicates a room is occupied?','“In use—please wait.”','“Empty and available.”','“Open to anyone now.”','房间有人使用时应标记 in use。'),Q(1,'If a person is occupied, the person is usually?','busy','uninhabited','for sale','occupied 也可形容人正忙。','meaning'),Q(1,'What is the opposite of an occupied room?','an unoccupied room','a booked room','a crowded room','occupied 与 unoccupied 相对。','confusable')]);
P('occupy','From Latin occupare “take possession of, seize,” formed from ob- “against, toward” + capere “take”; senses include using space/time, military control, keeping busy, and holding a post or residence.',[C('occupy.s1','通用','A large desk and two filing cabinets occupy most of the small office.','一张大桌子和两个文件柜占去了小办公室的大部分空间。','A large desk and two filing cabinets / occupy most of the small office.','occupy.s1 指占用空间或时间。','家具占据房间的一部分空间。'),C('occupy.s2','军事','Foreign troops occupied the harbor for six months before withdrawing under the treaty.','外国军队占领港口六个月，之后依条约撤离。','Foreign troops occupied the harbor / for six months / before withdrawing under the treaty.','occupy.s2 指军队进入并控制一地。','军队控制港口一段时间。'),C('occupy.s3','通用','The puzzle occupied the children throughout the long train ride.','漫长的火车旅途中，孩子们一直忙着玩拼图。','The puzzle occupied the children / throughout the long train ride.','occupy.s3 指让某人忙于某事，也可指占据思想。','拼图让孩子们一路有事可做。'),C('occupy.s4','书面','She occupies the chair of public health at the university and lives in an apartment nearby.','她在大学担任公共卫生讲席教授，并住在附近的公寓里。','She occupies the chair of public health / at the university / and lives in an apartment nearby.','occupy.s4 可指担任职位，也可指居住在某地。','占据讲席职位的用法较正式。')],M('The history book said the troops occupied the harbor while staying outside it and never taking control.','The history book said the troops occupied the harbor and controlled it for six months.','军事义的 occupy 表示进入并控制，不能仅在外观望。','distinction'),[Q(1,'What occupied most of the office?','A desk and two filing cabinets.','The harbor troops.','A university chair.','occupy.s1 指家具占用空间。'),Q(2,'What did the troops do to the harbor?','They took control of it.','They used a puzzle to entertain children.','They appointed a professor.','occupy.s2 表示军事占领。'),Q(3,'How did the puzzle affect the children?','It kept them busy.','It took military control of them.','It gave them a university post.','occupy.s3 可表示使某人忙碌。'),Q(4,'What does “occupies the chair” mean in the university sentence?','Holds the professorial position.','Sits in a movable seat temporarily.','Owns every chair in the building.','occupy.s4 可指担任正式职位。','distinction')]);
P('occur','From Latin occurrere “run to meet, present itself,” from ob- “toward” + currere “run”; English uses include an event happening, something existing, and an idea coming to mind.',[C('occur.s1','通用','Power failures occur more often during storms, when strong winds bring branches down onto cables.','暴风雨期间停电更常发生，因为强风会把树枝吹到电缆上。','Power failures occur more often during storms / when strong winds bring branches down / onto cables.','occur.s1 指事件发生。','停电是会发生的事件。'),C('occur.s2','科学','This rare mineral occurs only in a few deposits near the volcanic ridge.','这种稀有矿物只出现在火山脊附近的少数矿床中。','This rare mineral occurs only / in a few deposits / near the volcanic ridge.','occur.s2 指某物存在或出现在某处。','矿物在少数矿床中天然存在。'),C('occur.s3','心理','It did not occur to Nina that the unsigned envelope might contain the missing key.','妮娜没有想到那个未署名的信封里可能装着丢失的钥匙。','It did not occur to Nina / that the unsigned envelope might contain / the missing key.','occur.s3 表示想法进入某人脑海，常用 occur to someone。','念头没有浮现在妮娜脑中。')],M('The storm occurred the cable branch onto the road, according to the report.','The storm caused a branch to fall onto the cable, and a power failure occurred.','occur 是不及物动词，不能直接接宾语表示“造成”；需另用 cause。','grammar'),[Q(1,'When do power failures occur more often?','During storms.','Only on clear summer mornings.','When cables are removed from all towns.','occur.s1 表示故障发生。'),Q(2,'Where does the mineral occur?','In a few deposits near the volcanic ridge.','Inside Nina’s envelope.','On a storm cloud.','occur.s2 指矿物存在的地点。'),Q(3,'What did not occur to Nina?','That the envelope might hold the key.','That storms can damage cables.','That a mineral exists in deposits.','occur to 表示某念头浮现。'),Q(1,'Which sentence uses occur grammatically?','Several delays occurred this morning.','The driver occurred a red light.','She occurred the envelope to Nina.','occur 作“发生”时不及物，通常不直接带宾语。','grammar')]);
P('occur to','The phrase combines occur, from Latin occurrere “present itself,” with to; when a thought occurs to someone, it comes into that person’s mind.',C('occur to.s1','心理','It suddenly occurred to the surveyor that the old stone marker matched the map’s boundary line.','测绘员突然想到，那块旧石标与地图上的边界线相吻合。','It suddenly occurred to the surveyor / that the old stone marker / matched the map’s boundary line.','occur to someone 表示某个想法突然进入某人的脑海。','念头的接收者 surveyor 用 to 引出。'),M('The solution occurred the researcher after she checked the measurements.','The solution occurred to the researcher after she checked the measurements.','该结构要求 occur to someone，不能省去介词 to。','collocation'),[Q(1,'What occurred to the surveyor?','The marker matched the mapped boundary.','The map had turned into a stone.','The boundary had disappeared.','occur to.s1 表示一个想法浮现在测绘员脑中。'),Q(1,'Which pattern is correct for this meaning?','An idea occurred to someone.','Someone occurred an idea.','An idea occurred someone.','“念头浮现”用 occur to sb.','collocation'),Q(1,'When did the thought come to the surveyor?','After noticing the marker and map matched.','Before the map was drawn centuries ago.','Only after the stone was removed.','例句以发现两者吻合为触发点。','context'),Q(1,'Choose the grammatical sentence.','It occurred to me that we had met before.','It occurred me that we had met before.','I occurred the meeting yesterday.','正确结构是 occur to + 人。','grammar')]);
P('occurrence','From occur + noun-forming -ence, ultimately from Latin occurrere; it means an event or the fact that something happens.',C('occurrence.s1','通用','The unusual occurrence of snow in April delayed the orchard’s flowering by several days.','四月罕见降雪这一情况使果园的开花推迟了几天。','The unusual occurrence of snow in April / delayed the orchard’s flowering / by several days.','occurrence 可指发生的事件，也可指某事发生这一事实。','降雪是具体发生的事件。'),M('The report counted each occurrence as an event that had never happened and could not be observed.','The report counted each occurrence as an event that happened and was recorded.','occurrence 指已发生或出现的事，不代表永不可能观测。','meaning'),[Q(1,'What unusual occurrence delayed flowering?','Snow in April.','A summer drought in July.','A cancelled train ticket.','occurrence.s1 是四月降雪这一事件。'),Q(1,'What does occurrence refer to in the report?','An event or happening.','A person’s occupation.','A location where a mineral is stored.','occurrence 表示事件或发生。'),Q(1,'Which phrase is natural?','the occurrence of a rare event','the occurrence to a person an idea','the occurrence of a blue loudly','occurrence 常与 of 引出发生的事件。','collocation'),Q(1,'How is occurrence related to occur?','It is the noun for an event or happening.','It is the past tense of occur.','It means the opposite of happening.','occurrence 是 occur 的名词形式之一。','word-formation')]);
P('ocean','From Old French occean and Latin oceanus, from Greek Ōkeanos, the name of the great stream surrounding the world in Greek cosmology; later the vast salt-water body and, figuratively, a huge amount.',[C('ocean.s1','地理','The research vessel crossed the Pacific Ocean while measuring temperature at several depths.','科考船横渡太平洋，并测量了多个深度的水温。','The research vessel crossed the Pacific Ocean / while measuring temperature / at several depths.','ocean.s1 指大片咸水海域。','Pacific Ocean 是地球上的大洋之一。'),C('ocean.s2','口语','After the storm, the volunteers faced an ocean of paperwork before they could distribute supplies.','风暴过后，志愿者要处理堆积如海的文书，才能分发物资。','After the storm / the volunteers faced an ocean of paperwork / before they could distribute supplies.','ocean.s2 可比喻数量极大的一片事物。','海量文书是数量的比喻。')],M('The crew crossed an ocean of paperwork by sailing their ship through the office files.','The crew crossed the ocean while volunteers faced an ocean of paperwork at the office.','ocean 的字面义是大洋；“文书之海”才是比喻用法。','distinction'),[Q(1,'Which body of water did the vessel cross?','The Pacific Ocean.','A filing cabinet.','A small freshwater pond.','ocean.s1 指广阔咸水海域。'),Q(2,'What does an ocean of paperwork mean?','A very large amount of paperwork.','Paper floating on the Pacific.','A single document about storms.','ocean.s2 是“大量”的比喻义。'),Q(1,'Which is an ocean?','The Atlantic.','A neighborhood swimming pool.','A puddle after rain.','大西洋是地球上的大洋。','meaning'),Q(2,'Why is “ocean of paperwork” figurative?','It compares a large quantity to a vast body of water.','The paperwork is literally salt water.','It describes a ship’s navigation chart.','此处 ocean 强调数量巨大。','distinction')]);
P('Oceania','Named from ocean with the region-forming suffix -ia; the geographical name was popularized in French as Océanie in the early nineteenth century.',C('Oceania.s1','地理','The atlas groups Australia, New Zealand, and many Pacific island nations within Oceania.','这本地图册把澳大利亚、新西兰和许多太平洋岛国划入大洋洲。','The atlas groups Australia, New Zealand, and many Pacific island nations / within Oceania.','Oceania 是以太平洋岛屿为核心、通常也包括澳大利亚和新西兰的地理区域名。','地图册采用包含澳新及太平洋岛国的区域划分。'),M('The atlas placed Oceania entirely in the North Atlantic, between Europe and North America.','The atlas placed Oceania in the Pacific region, including Australia and many Pacific islands.','Oceania 位于太平洋区域，不在北大西洋。','meaning'),[Q(1,'Which places does the atlas group in Oceania?','Australia, New Zealand, and Pacific island nations.','Only countries around the North Atlantic.','The Mediterranean coast of Europe.','Oceania.s1 是太平洋地区的地理名称。'),Q(1,'Oceania is named in relation to which feature?','The ocean and Pacific islands.','An ancient Roman road.','A mountain range in central Europe.','名称源自 ocean。','word-formation'),Q(1,'Which is a likely part of Oceania?','Fiji.','Iceland.','Portugal.','斐济是太平洋岛国。','meaning'),Q(1,'Why is Oceania a regional name rather than one country’s name?','It covers a geographic group of lands and islands.','It names one city on the Mediterranean.','It refers only to an ocean current.','该词指一个区域，包含多个国家和岛屿。','distinction')]);
P('oceanic','From ocean + -ic, the adjective relating to the ocean; in geology, oceanic crust is the crust beneath ocean basins.',C('oceanic.s1','自然','The team sampled oceanic water far from the coast to compare its salinity with the river plume.','团队在远离海岸的海洋水域取样，将其盐度与河流冲淡水作比较。','The team sampled oceanic water / far from the coast / to compare its salinity / with the river plume.','oceanic 表示与海洋有关。','取样地点在远离海岸的海域。'),M('The report called a freshwater lake oceanic simply because it was deep.','The report called the offshore seawater oceanic because it was part of the ocean.','深度本身不能使淡水湖成为 oceanic；该词与海洋有关。','word-choice'),[Q(1,'Where did the team collect oceanic water?','Far from the coast.','In a freshwater lake.','Inside a dry laboratory cupboard.','oceanic water 是海洋中的水。'),Q(1,'What does oceanic mean?','Related to the ocean.','Belonging to a desert only.','Made entirely of salt crystals.','-ic forms an adjective meaning related to ocean.','word-formation'),Q(1,'Which phrase fits oceanic?','oceanic current','oceanic teaspoon','oceanic bedtime alarm','洋流与海洋有关。','collocation'),Q(1,'Why compare oceanic water with a river plume?','Their salinity and water properties may differ.','Both are kinds of office furniture.','Oceanic means the water is frozen.','研究比较海水与河流淡水的盐度。','context')]);
P('oceanographer','From oceanography + agent suffix -er; an oceanographer is a scientist who studies the sea and its physical, chemical, or biological systems.',C('oceanographer.s1','科学','The oceanographer lowered a sensor through the water column to record temperature, salinity, and depth.','海洋学家把传感器放入整层水体，记录温度、盐度和深度。','The oceanographer lowered a sensor / through the water column / to record temperature, salinity, and depth.','oceanographer 指研究海洋的科学家。','测量海水性质是海洋学研究工作。','word-formation'),M('The article called the ship’s cook an oceanographer solely because the cook served lunch at sea.','The article called the scientist studying seawater an oceanographer.','在海上工作不等于研究海洋；该词指海洋科学研究者。','distinction'),[Q(1,'What did the oceanographer use?','A sensor.','A fishing net to catch office papers.','A telescope for studying planets only.','海洋学家用传感器测量水体。'),Q(1,'What does an oceanographer study?','The sea and its systems.','Only mountain forests.','The history of office furniture.','oceanographer 是海洋研究者。'),Q(1,'Which task fits an oceanographer?','Measuring salinity at different depths.','Recording the color of a city bus.','Calculating a hotel’s room occupancy.','盐度和深度是海洋研究内容。','context'),Q(1,'How is oceanographer formed?','oceanography + -er','ocean + past-tense -ed','oceanic + plural -s','-er forms an agent noun from oceanography.','word-formation')]);
P('oceanographic','From oceanography + -ic, meaning related to the scientific study of the sea or to measurements collected at sea.',C('oceanographic.s1','科学','The archive contains oceanographic charts showing temperature and current patterns across the basin.','档案馆保存着海洋学图表，展示该海盆的温度和洋流模式。','The archive contains oceanographic charts / showing temperature and current patterns / across the basin.','oceanographic 表示海洋学的、与海洋研究相关的。','图表呈现海温与洋流等研究数据。'),M('The museum labeled a list of restaurant menus oceanographic data because several restaurants served seafood.','The museum labeled measurements of currents and sea temperatures as oceanographic data.','海鲜菜单不是海洋学数据；洋流和海温才是。','word-choice'),[Q(1,'What did the oceanographic charts show?','Temperature and current patterns.','Restaurant prices in a city.','A list of mountain trails.','oceanographic.s1 是海洋研究图表。'),Q(1,'Which phrase naturally uses oceanographic?','oceanographic survey','oceanographic dessert','oceanographic shoelace','survey 可描述海洋学调查。','collocation'),Q(1,'What is oceanographic data about?','The ocean and its measured conditions.','Only the weather inside a classroom.','A person’s job title.','该形容词指海洋学相关数据。','meaning'),Q(1,'What base word is oceanographic related to?','oceanography','octagon','occupancy','oceanographic is formed from oceanography + -ic.','word-formation')]);
P('oceanography','From ocean + -graphy, a combining form meaning writing, description, or study; the word names the science of the ocean and its life and processes.',C('oceanography.s1','科学','Oceanography combines field observations and laboratory work to explain tides, currents, and marine ecosystems.','海洋学结合实地观测与实验室研究，解释潮汐、洋流和海洋生态系统。','Oceanography combines field observations and laboratory work / to explain tides, currents, and marine ecosystems.','oceanography 是研究海洋、海洋生物及其运动过程的科学。','潮汐、洋流和生态系统都是海洋学研究对象。','word-formation'),M('The syllabus described oceanography as the study of inland traffic lights and city parking rules.','The syllabus described oceanography as the study of oceans, marine life, and sea processes.','该学科研究海洋及其过程，不研究城市交通规则。','word-choice'),[Q(1,'Which topics does oceanography address in the example?','Tides, currents, and marine ecosystems.','Parking meters and traffic lights.','The history of hotel occupancy.','oceanography.s1 是海洋研究领域。'),Q(1,'What does -graphy contribute to oceanography?','A sense of study or description.','A sense of past tense.','A sense of a single person.','-graphy 常构成学科或描述类名词。','word-formation'),Q(1,'Which professional would most likely study oceanography?','A marine scientist.','A city parking officer.','A theater ticket seller.','海洋学家研究海洋。','context'),Q(1,'Oceanography is chiefly the scientific study of?','the ocean and its processes','eight-sided polygons','occupied office rooms','定义直接说明其研究对象是海洋。','meaning')]);
P('ocher','From French ocre, from Latin ochra and Greek ōkhra, a yellow earth pigment; the spelling ochre is also standard, especially in British English.',C('ocher.s1','艺术','The conservator mixed ocher with water to retouch the warm yellow-brown border of the mural.','修复师把赭土颜料与水调和，修补壁画上暖黄褐色的边饰。','The conservator mixed ocher with water / to retouch / the warm yellow-brown border / of the mural.','ocher 指富含氧化铁的天然土质颜料，也指由此得到的黄褐色。','颜料用于修补呈赭黄色调的壁画。'),M('The conservator used a clear liquid called ocher to remove every trace of color from the mural.','The conservator used a yellow-brown earth pigment called ocher to retouch the mural.','ocher 是一种有颜色的天然土质颜料，不是透明去色液。','word-choice'),[Q(1,'What did the conservator mix with water?','A yellow-brown earth pigment.','A clear paint remover.','A sheet of newsprint.','ocher.s1 指天然土质颜料。'),Q(1,'Which color is commonly associated with ocher?','Yellow-brown.','Bright blue.','Colorless.','赭土常呈黄褐色。','meaning'),Q(1,'Why was ocher used on the mural?','To retouch its warm yellow-brown border.','To measure the room’s occupancy.','To darken the ocean water.','例句说明颜料用于修补边饰。','context'),Q(1,'Which spelling is also accepted for the pigment?','ochre','octher','ochered','ochre is a standard variant spelling.','spelling')]);
P('octagon','From Greek oktagōnon, from okto “eight” + gōnia “angle”; an octagon is a polygon with eight sides and eight angles.',C('octagon.s1','数学','The carpenter cut each of the eight sides of the octagon to the same length before assembling the frame.','木匠在组装框架前，把八角形的八条边都切成同样长度。','The carpenter cut each of the eight sides / of the octagon / to the same length / before assembling the frame.','octagon 指有八条边和八个角的多边形。','“eight sides”直接体现八边形特征。'),M('The worksheet called a six-sided stop sign an octagon.','The worksheet called the eight-sided stop sign an octagon.','octagon 有八条边；六边形不是 octagon。','number'),[Q(1,'How many sides did the octagon have?','Eight.','Six.','Ten.','octagon.s1 有八条边。','number'),Q(1,'What did the carpenter make equal?','The lengths of all eight sides.','The number of windows in the shop.','The angles of a triangle.','木匠把八条边切成同样长度。'),Q(1,'Which shape is an octagon?','A polygon with eight sides.','A polygon with five sides.','A circle with no sides.','八边形有八条直边。','meaning'),Q(1,'The element octa- in octagon points to?','eight','one hundred','a curved surface','Greek okto means eight.','word-formation')]);
P('October','From Latin October, from octo “eight”; it was the eighth month in the early Roman calendar, before January and February were added.',[C('October.s1','时间','The museum will reopen in October, after the conservation team finishes its summer repairs.','博物馆将在十月重新开放，届时修复团队已完成夏季维修。','The museum will reopen in October / after the conservation team finishes / its summer repairs.','October.s1 是九月之后、十一月之前的月份。','月份顺序指向十月。'),C('October.s2','时间','October was unusually warm that year, so the orchard kept its outdoor market open for another week.','那年十月异常温暖，因此果园的户外集市又延长了一周。','October was unusually warm that year / so the orchard kept its outdoor market open / for another week.','October.s2 可指某一年的十月及其天气、活动等。','句子描述具体某年的十月天气。')],M('The calendar marked October immediately after November.','The calendar marked October after September and before November.','October 位于 September 之后、November 之前。','number'),[Q(1,'When will the museum reopen?','In October.','In August.','After the following December only.','October.s1 指十月份。'),Q(2,'Why did the orchard extend its outdoor market?','That October stayed unusually warm.','The museum’s rooms were occupied.','The octagon had fewer sides.','October.s2 指那一年的十月天气。'),Q(1,'Which month comes immediately after September?','October.','November.','August.','October 紧随 September。','number'),Q(1,'Why was October originally the eighth month?','The early Roman year began with March.','It has eight letters in English.','It always lasts eight days.','名称来自拉丁语 octo “八”，因其早期历法位置。','word-formation')]);

P('octopus','From Greek oktōpous, literally “eight-footed,” from oktō “eight” + pous “foot”; the plural most often used in English is octopuses.',C('octopus.s1','生物','The octopus squeezed through a narrow opening by folding its soft body and drawing its eight arms behind it.','章鱼把柔软的身体挤过狭窄开口，并把八条腕收在身后。','The octopus squeezed through a narrow opening / by folding its soft body / and drawing its eight arms behind it.','octopus 是有八条腕、身体柔软的海洋动物。','八条腕是章鱼的显著特征。'),M('The aquarium sign described an octopus as a hard-shelled fish with six legs.','The aquarium sign described an octopus as a soft-bodied sea animal with eight arms.','章鱼柔软无硬壳，具有八条腕。','meaning'),[Q(1,'How did the octopus pass through the opening?','It folded its soft body and drew in its arms.','It opened a hard shell and used six legs.','It turned into a fish.','octopus.s1 指柔软身体、八腕的海洋动物。'),Q(1,'How many arms does an octopus have?','Eight.','Six.','Ten.','Greek oktō means eight.','number'),Q(1,'Which plural is standard in ordinary English?','octopuses','octopi only','octopodes only','octopuses is the usual English plural.','plural'),Q(1,'What allowed the animal to squeeze through the gap?','Its soft body.','A rigid shell.','A pair of wings.','软体身体可以挤过狭窄缝隙。','context')]);
P('ocular','From Latin ocularis “of the eyes,” from oculus “eye”; it is an adjective relating to the eye or vision.',C('ocular.s1','健康','The optometrist used an ocular examination to check the patient’s eyes after the reported flashes of light.','患者报告看到闪光后，验光师进行眼部检查。','The optometrist used an ocular examination / to check the patient’s eyes / after the reported flashes of light.','ocular 表示眼睛的、与视觉器官有关的。','检查对象是患者的眼睛。'),M('The chart called a hearing test an ocular examination even though it assessed no eye function.','The chart called the eye-function assessment an ocular examination.','ocular 指眼部，听力检查不属于 ocular examination。','word-choice'),[Q(1,'What did the ocular examination check?','The patient’s eyes.','The patient’s hearing.','The patient’s balance only.','ocular.s1 与眼睛有关。'),Q(1,'Which phrase uses ocular correctly?','ocular muscles','ocular rainfall','ocular timetable','眼肌是与眼睛有关的结构。','collocation'),Q(1,'What does ocular derive from?','A Latin word for eye.','A Greek word for eight.','A Latin word for ocean.','oculus means “eye.”','word-formation'),Q(1,'Which specialist would likely perform an ocular exam?','An optometrist.','An oceanographer.','A hotel manager.','验光师检查视觉和眼睛。','context')]);
P('odd','From Old Norse oddi “point of a weapon,” later “third or odd number”; senses include strange, not divisible by two, unmatched, and occasional.',[C('odd.s1','通用','It seemed odd that the lighthouse lamp was on in broad daylight, so the keeper checked the timer.','灯塔的灯在大白天亮着，显得很奇怪，于是看守检查了定时器。','It seemed odd / that the lighthouse lamp was on in broad daylight / so the keeper checked the timer.','odd.s1 指奇怪的、不同寻常的。','白天开灯不符合常态。'),C('odd.s2','数学','The number 27 is odd because dividing it by two leaves a remainder of one.','27是奇数，因为除以二会余一。','The number 27 is odd / because dividing it by two / leaves a remainder of one.','odd.s2 指不能被二整除的奇数。','27 ÷ 2 余1。'),C('odd.s3','通用','She found an odd glove beneath the bench, but its matching glove was nowhere nearby.','她在长椅下发现一只零散的手套，却没有在附近找到配对的另一只。','She found an odd glove / beneath the bench / but its matching glove was nowhere nearby.','odd.s3 指不成对或剩下的单只物品。','只有一只手套，没有配对的一只。'),C('odd.s4','通用','He does the odd repair for neighbors, usually fixing a loose hinge or a dripping tap.','他偶尔帮邻居做些零星维修，通常是修松动的铰链或漏水的水龙头。','He does the odd repair for neighbors / usually fixing a loose hinge / or a dripping tap.','odd.s4 指偶尔发生的、零星的。','odd repair 表示偶尔接的维修活。')],M('The teacher called 28 odd because it leaves a remainder when divided by two.','The teacher called 28 even because it divides by two with no remainder.','28 能被2整除，是偶数而非奇数。','number'),[Q(1,'Why did the lighthouse lamp seem odd?','It was on in broad daylight.','It was off at midnight.','It was painted white.','odd.s1 表示不寻常。'),Q(2,'Why is 27 odd?','It leaves a remainder when divided by two.','It is divisible by two with no remainder.','It has eight arms.','odd.s2 是奇数义。'),Q(3,'What was odd about the glove?','It had no matching partner nearby.','It was a pair of two gloves.','It was worn on both hands.','odd.s3 指落单或不成对。'),Q(4,'“The odd repair” most nearly means?','An occasional repair.','A mathematically odd repair.','A repair that is always strange.','odd.s4 可表示偶尔、零星的。','meaning')]);
P('odd one out','An idiomatic noun phrase: odd means “different from the others,” and one out is the member outside a matching group.',C('odd one out.s1','社交','Among the three metal spoons and one wooden spoon, the wooden one was the odd one out.','三把金属勺和一把木勺放在一起时，木勺显得格格不入。','Among the three metal spoons and one wooden spoon / the wooden one / was the odd one out.','odd one out 指一组中与其他成员不同的人或物。','木勺的材质不同于其余三把。'),M('The four matching blue cups included one odd one out even though each cup was identical.','The set had an odd one out because one cup was red while the others were blue.','odd one out 必须有明显差异；完全相同的一组里没有异类。','distinction'),[Q(1,'Why was the wooden spoon the odd one out?','Its material differed from the three metal spoons.','It was one of the metal spoons.','The other spoons were made of wood.','odd one out 表示组内唯一不同者。'),Q(1,'Which is the odd one out: oak, pine, birch, granite?','granite','oak','pine','granite is a rock; the others are trees.','word-choice'),Q(1,'What can odd one out describe?','A member that differs from its group.','Every identical member of a set.','The middle item in a numbered list.','该短语强调组内的差异成员。'),Q(1,'In the example, how many spoons were metal?','Three.','One.','Four.','三把金属勺中，木勺是唯一不同的一把。','number')]);
P('oddity','From odd + the noun-forming suffix -ity; it denotes a strange feature, event, or person.',C('oddity.s1','性格','The clock’s backward-moving hands were an oddity that drew visitors to the small museum.','这座钟逆向移动的指针是一件奇事，吸引游客来到这家小博物馆。','The clock’s backward-moving hands / were an oddity / that drew visitors / to the small museum.','oddity 指奇怪的人、事或不寻常的性质。','指针逆行是吸引人的异常现象。'),M('The curator called the ordinary clock an oddity although its hands moved normally and it had no unusual feature.','The curator called the backward-running clock an oddity because its mechanism was unusual.','oddity 指不寻常之处，普通且正常的事物不构成奇事。','meaning'),[Q(1,'What was the museum’s oddity?','A clock whose hands moved backward.','A clock with ordinary forward-moving hands.','A visitor’s ticket.','oddity.s1 指吸引注意的奇特事物。'),Q(1,'Which is an oddity?','A lake that naturally changes color each season.','A standard chair in a furniture shop.','A routine appointment at noon.','季节变色的湖有不寻常之处。','meaning'),Q(1,'What does the suffix -ity do in oddity?','Forms a noun for a quality or thing.','Forms a past-tense verb.','Marks a plural adjective.','odd + -ity forms the noun oddity.','word-formation'),Q(1,'Why did visitors come to the museum?','To see the unusual clock.','To repair the town’s roads.','To buy metal spoons.','逆行指针这件奇事吸引了游客。','context')]);
P('oddly','From odd + the adverb-forming suffix -ly; it means in a strange or unexpected way and also appears in the phrase oddly enough.',C('oddly.s1','通用','Oddly, the old radio received a clear signal only when it was placed beside the closed window.','奇怪的是，旧收音机只有放在关着的窗户旁边才能收到清晰信号。','Oddly / the old radio received a clear signal / only when it was placed / beside the closed window.','oddly 表示以奇怪或出乎意料的方式。','句首副词表达说话者对结果感到意外。'),M('The report used oddly to mean “in the usual, expected way.”','The report used oddly to mean “in a strange or unexpected way.”','oddly 的意思是奇怪地，并非照常地。','meaning'),[Q(1,'What was unusual about the radio?','It worked clearly only beside the closed window.','It received no signal anywhere.','It worked only when the window was removed.','oddly 引出一个反常结果。'),Q(1,'Which phrase is close in meaning to oddly enough?','strangely enough','as expected','at the correct angle','oddly enough 意为奇怪的是。','meaning'),Q(1,'How is oddly formed?','odd + -ly','odd + plural -s','odds + past -ed','-ly forms an adverb from odd.','word-formation'),Q(1,'Which sentence uses oddly correctly?','Oddly, the empty room echoed more than the hall.','Oddly, the room was exactly as expected and ordinary.','She oddly the lamp yesterday.','副词 oddly 修饰整个出乎意料的情况。','grammar')]);
P('odds','From odd, originally associated with unequal or differing things; plural odds means chances, betting ratios, or disagreement in the phrase at odds.',[C('odds.s1','通用','The odds of a clear night improved after the storm moved east, so the astronomers kept the telescope ready.','风暴向东移动后，天晴的可能性提高了，因此天文学家让望远镜保持待用。','The odds of a clear night improved / after the storm moved east / so the astronomers kept the telescope ready.','odds.s1 指某事发生的可能性。','天气转晴使观测成功的机会变大。'),C('odds.s2','博彩','The bookmaker offered odds of five to one on the outsider winning the race.','博彩公司为冷门选手赢得比赛开出了五比一的赔率。','The bookmaker offered odds of five to one / on the outsider winning the race.','odds.s2 指投注赔率，表示投注与回报的比例。','five to one 是赔率表达方式。'),C('odds.s3','通用','The two sisters were at odds over how to restore their grandfather’s workshop.','两姐妹在如何修复祖父的工坊这件事上意见不合。','The two sisters were at odds / over how to restore / their grandfather’s workshop.','at odds 表示彼此意见不一致。','姐妹们对修复方案有分歧。')],M('The sisters were at odds because they agreed completely on every part of the restoration plan.','The sisters were at odds because they disagreed about the restoration plan.','at odds 表示有分歧，而不是完全一致。','distinction'),[Q(1,'What improved after the storm moved east?','The chance of a clear night.','The bookmaker’s five-to-one payout.','The sisters’ disagreement.','odds.s1 表示发生的可能性。'),Q(2,'What did five to one describe?','Betting odds.','The number of telescope lenses.','The sisters’ ages.','odds.s2 指赔率比例。'),Q(3,'What were the sisters at odds about?','How to restore the workshop.','Whether the storm had moved east.','The meaning of a five-to-one bet.','at odds 指意见不一致。'),Q(1,'Which phrase means “a small chance”?','long odds','at odds','odd one out','Long odds can indicate a low likelihood.','meaning')]);
P('ode','From French ode, from Greek ōidē “song”; an ode is a formal lyric poem, often addressing or praising a subject.',C('ode.s1','文学','The poet wrote an ode to the river, praising the water that sustained the valley’s farms and wildlife.','诗人写了一首颂歌赞美河流，称颂滋养山谷农田和野生生物的河水。','The poet wrote an ode to the river / praising the water / that sustained the valley’s farms and wildlife.','ode 指形式较庄重、常用来赞美或抒情的诗。','诗作直接赞美河流。'),M('The anthology labeled a grocery receipt an ode even though it contained no poetic praise or reflection.','The anthology labeled the poem praising the river an ode.','ode 是诗歌体裁，不是普通收据。','word-choice'),[Q(1,'What was the ode about?','The river and its value to the valley.','A shopping receipt.','The odds of a clear night.','ode.s1 是赞美河流的诗。'),Q(1,'Which is most likely an ode?','A formal lyric poem praising spring.','A list of store prices.','A bus timetable.','颂歌常以诗歌形式赞美对象。','meaning'),Q(1,'Where does the word ode trace back to?','Greek for song.','Latin for eye.','Old Norse for point.','Greek ōidē means “song.”','word-formation'),Q(1,'Why does the poet praise the river?','It sustains farms and wildlife.','It controls the hotel’s occupancy.','It carries a betting price.','例句给出了河流的重要作用。','context')]);
P('odor','From Latin odor “smell, scent”; it means a smell, especially a noticeable one, and figuratively a lingering atmosphere or reputation.',[C('odor.s1','通用','A sharp odor of burned wiring spread through the hallway, so the caretaker cut the power and called an electrician.','走廊里弥漫着刺鼻的焦线气味，因此管理员切断电源并叫来电工。','A sharp odor of burned wiring / spread through the hallway / so the caretaker cut the power / and called an electrician.','odor.s1 指可以闻到的气味，常强调明显或难闻。','焦线气味提示电路可能过热。'),C('odor.s2','书面','The bribery scandal left an odor of suspicion around the entire bidding process.','贿赂丑闻给整个招标过程蒙上了可疑的阴影。','The bribery scandal left an odor of suspicion / around the entire bidding process.','odor.s2 可比喻围绕某事的挥之不去的气氛或名声。','suspicion 是名声上的比喻“气味”。')],M('The electrician called the suspicion around the bid a literal odor that could be smelled in the hallway.','The article described the suspicion surrounding the bid as an odor in the figurative sense.','怀疑的气氛不是实际气味；这里用 odor 作比喻。','distinction'),[Q(1,'What odor spread through the hallway?','The smell of burned wiring.','The smell of fresh bread.','A sound from the alarm.','odor.s1 指可闻到的气味。'),Q(2,'What did the scandal leave around the bidding process?','A lingering suspicion.','A scent of wiring smoke.','A clean safety record.','odor.s2 是气氛或名声的比喻义。'),Q(1,'Which sense is physical?','An odor of smoke in a room.','An odor of suspicion around a deal.','The odor of dishonesty in a metaphor.','烟味能直接闻到。','distinction'),Q(1,'Why did the caretaker cut the power?','The odor suggested burned wiring.','The bidding process was at odds.','A poem praised the hallway.','焦线气味让管理员担心电气故障。','context')]);
P('odorless','From odor + -less, meaning without smell; the ending -less forms adjectives meaning “lacking.”',C('odorless.s1','科学','The laboratory chose an odorless solvent so the staff could detect other chemical smells more easily.','实验室选择无味溶剂，以便工作人员更容易察觉其他化学气味。','The laboratory chose an odorless solvent / so the staff could detect / other chemical smells / more easily.','odorless 表示不散发气味。','无味溶剂不会掩盖其他气味。','word-formation'),M('The label described the strongly scented solvent as odorless.','The label described the solvent with no detectable smell as odorless.','odorless 与有明显气味相反。','distinction'),[Q(1,'Why did the laboratory choose an odorless solvent?','So other chemical smells would be easier to detect.','To hide every chemical leak with perfume.','Because it had a strong scent.','odorless.s1 表示没有气味。'),Q(1,'What does -less mean in odorless?','Without or lacking.','Full of.','Able to become.','-less forms “lacking odor.”','word-formation'),Q(1,'Which item is odorless?','A substance with no detectable smell.','A perfume with a strong fragrance.','A smoke-filled room.','无味物质没有可察觉的气味。','meaning'),Q(1,'Which word is the opposite of odorless?','odorous','octagonal','occupied','odorous means giving off a smell.','confusable')]);
P('odorous','From Latin odorus “fragrant,” from odor “smell”; odorous means giving off a smell, which may be pleasant or strong.',C('odorous.s1','通用','The odorous herbs filled the kitchen with a warm scent as they simmered in the pot.','有香气的香草在锅中慢炖时，让厨房充满温暖的气味。','The odorous herbs / filled the kitchen with a warm scent / as they simmered in the pot.','odorous 指散发气味的，气味可以好闻或浓烈。','香草释放出温暖的香气。'),M('The guide called the herbs odorless even though their strong fragrance filled the room.','The guide called the strongly scented herbs odorous.','明显释放香气的东西是 odorous，不是 odorless。','confusable'),[Q(1,'What filled the kitchen?','A warm scent from the herbs.','A silent visual pattern.','An empty pot with no ingredients.','odorous.s1 指散发气味。'),Q(1,'Does odorous always mean unpleasant?','No; it can describe a pleasant or strong smell.','Yes; it only means rotten.','Yes; it means no smell at all.','odorous 可指任何明显气味，不限于恶臭。'),Q(1,'Which is odorous?','Fresh basil releasing its aroma.','A sealed object with no detectable smell.','A silent electric current.','香草散发气味，是 odorous。','meaning'),Q(1,'How does odorous contrast with odorless?','Odorous gives off a smell; odorless does not.','Both mean completely scent-free.','Odorless means unusually fragrant.','两词在是否有气味上相反。','confusable')]);
P('Odyssey','From Greek Odysseia, the title of Homer’s epic about Odysseus’s long return voyage; the capitalized title also gives English a figurative sense of a long, eventful journey.',C('Odyssey.s1','文学','The memoir follows the climber’s twenty-year Odyssey from a coastal village to the summit of several continents.','这本回忆录讲述了登山者从海边村庄出发、历时二十年攀登多洲高峰的漫长历险。','The memoir follows the climber’s twenty-year Odyssey / from a coastal village / to the summit of several continents.','Odyssey 可指荷马史诗《奥德赛》，也可比喻漫长而充满波折的旅程。','二十年的登山经历借用史诗主人公的漫长归途作比。'),M('The review called a ten-minute walk to the mailbox an Odyssey despite no difficulty or adventure.','The review called the climber’s long, difficult expedition an Odyssey.','Odyssey 的比喻义强调漫长且富有历险或变故的旅程。','meaning'),[Q(1,'How long was the climber’s Odyssey?','Twenty years.','Ten minutes.','One afternoon.','Odyssey.s1 用来比喻漫长历险。','number'),Q(1,'Which work gives Odyssey its original literary association?','Homer’s epic about Odysseus.','A Roman calendar.','A Greek geometry textbook.','英文词源来自荷马史诗标题。','word-formation'),Q(1,'Which experience could be called an odyssey figuratively?','A long journey full of setbacks and discoveries.','A short routine walk across one room.','A single meal at home.','比喻义指漫长且多波折的行程。','meaning'),Q(1,'Why is Odyssey capitalized in the sentence’s source?','It is the title of a classical epic.','It is the name of an ocean.','It is a plural noun.','作为史诗标题时首字母大写。','capitalization')]);
P('of','From Old English of, related to off and from; the preposition marks possession/association, contents or measure, material, subject, and cause.',[C('of.s1','语法','The handle of the brass kettle became hot after the water boiled for several minutes.','水沸腾几分钟后，黄铜水壶的把手变热了。','The handle of the brass kettle / became hot / after the water boiled / for several minutes.','of.s1 可表示所属或整体与部分关系。','把手属于水壶的一部分。'),C('of.s2','语法','A bowl of rice and a glass of water were left on the table for the late guest.','桌上给来客留了一碗米饭和一杯水。','A bowl of rice and a glass of water / were left on the table / for the late guest.','of.s2 可表示容器所装内容或数量单位。','米饭是碗中所装之物，水是杯中所装之物。'),C('of.s3','语法','The sculpture is made of recycled glass collected from neighborhood workshops.','这座雕塑由从社区工坊收集来的回收玻璃制成。','The sculpture is made of recycled glass / collected from neighborhood workshops.','of.s3 可引出制成某物的材料。','玻璃是雕塑所用材料。'),C('of.s4','语法','The lecture was about the history of public libraries in rural towns.','讲座内容是乡镇公共图书馆的历史。','The lecture was about the history / of public libraries / in rural towns.','of.s4 可表示关于某个主题或对象。','图书馆的历史是讲座主题。'),C('of.s5','语法','The patient died of pneumonia despite receiving prompt treatment.','患者尽管及时治疗，仍因肺炎去世。','The patient died of pneumonia / despite receiving prompt treatment.','of.s5 可表示疾病或其他原因；died of pneumonia 是常见搭配。','of 引出死亡原因，搭配自然常见。')],M('The sculpture is made of recycled glass; here, of tells what the sculpture contains.','The sculpture is made of recycled glass; here, of tells what material it uses.','此处 of 引出制作材料，不是说玻璃是雕塑所装的内容。','distinction'),[Q(1,'In “the handle of the kettle,” what does of express?','A part-to-whole relationship.','The material used to make the handle.','A cause of illness.','of.s1 表示把手属于水壶整体。'),Q(2,'In “a bowl of rice,” what does of introduce?','The contents of the bowl.','The bowl’s owner.','A topic for a lecture.','of.s2 表示容器内装的东西。'),Q(3,'In “made of recycled glass,” what does of identify?','The material.','The destination.','A disagreement.','of.s3 引出制作材料。'),Q(4,'In “a lecture about the history of libraries,” what does of connect?','The subject being discussed.','The number of glasses.','A cause of fever.','of.s4 表示主题或对象。','grammar')]);
P('of course','From of + course, an adverbial phrase that developed the sense “as a matter of course”; it expresses agreement, certainty, or a point the speaker treats as obvious.',C('of course.s1','口语','“Could you check the address before we leave?” “Of course,” Maya replied, opening the message.','“我们出发前你能核对一下地址吗？”“当然可以。”玛雅一边回答一边打开消息。','“Could you check the address / before we leave?” / “Of course,” Maya replied / opening the message.','of course 常用于表示同意、肯定或理所当然。','回答表示愿意核对地址。'),M('“Can you help?” “Of course not,” he said while eagerly carrying the boxes upstairs.','“Can you help?” “Of course,” he said and carried the boxes upstairs.','of course 通常肯定回应；后续行动也应与同意一致。','context'),[Q(1,'What did Maya agree to do?','Check the address.','Cancel the trip.','Hide the message.','of course.s1 表示同意帮忙。'),Q(1,'Which answer most naturally means “certainly”?','Of course.','At odds.','Of late.','of course 可表示当然、当然可以。','meaning'),Q(1,'What does of course convey in Maya’s reply?','Agreement to the request.','Disagreement with the address.','A report of a past event.','她接受了核对地址的请求。','context'),Q(1,'Which phrase is punctuated as a brief reply?','“Of course,” Maya said.','“Of course Maya said” with no comma or closing mark.','“Of, course” as two unrelated words.','作为插入式回应时，短语与引述语之间用逗号。','punctuation')]);
P('of late','A fixed prepositional phrase, of + late, in which late means “recently”; it is a formal or literary way to say lately.',C('of late.s1','书面','The river has risen twice of late, prompting the town to inspect the flood barriers again.','近来河水已经两次上涨，促使镇上再次检查防洪屏障。','The river has risen twice of late / prompting the town / to inspect the flood barriers again.','of late 是较正式的“近来、最近”。','twice of late 表示近期已发生两次。','register'),M('The diary used of late to describe an event scheduled for next year.','The diary used of late to describe events that had happened recently.','of late 表示近期，不表示未来某个时间。','meaning'),[Q(1,'How many times had the river risen of late?','Twice.','Never.','Every year for a century.','of late.s1 指近期发生的情况。'),Q(1,'Which phrase is closest in meaning to of late?','recently','in the distant future','at once','of late means recently.','meaning'),Q(1,'Which style most suits of late?','Formal or literary prose.','A technical plural marker.','A casual counting word for eight.','该固定短语较正式或带文学色彩。','register'),Q(1,'What did the river’s recent rise prompt the town to do?','Inspect the flood barriers again.','Close every library.','Change the month on the calendar.','河水上涨促使镇上复查防洪设施。','context')]);
P('of one mind','An idiom built from one mind for shared opinion; to be of one mind means to agree about a decision or belief.',C('of one mind.s1','商务','After comparing the cost estimates, the committee was of one mind that the safer bridge design should be chosen.','比较成本估算后，委员会一致认为应选择更安全的桥梁设计。','After comparing the cost estimates / the committee was of one mind / that the safer bridge design should be chosen.','of one mind 表示对某事意见一致。','委员会共同赞成更安全的方案。'),M('The committee was of one mind because half supported the bridge plan and half rejected it.','The committee was divided because half supported the bridge plan and half rejected it.','立场相反的两组人意见不一致，不能说 of one mind。','distinction'),[Q(1,'What did the committee agree on?','Choosing the safer bridge design.','Rejecting every design without discussion.','Raising the cost estimate.','of one mind.s1 表示意见一致。'),Q(1,'Which phrase is closest to of one mind?','in agreement','at odds','out of service','of one mind means in agreement.','meaning'),Q(1,'What did the committee compare?','Cost estimates.','Ocean poems.','Hotel occupancy charts.','例句说他们先比较了成本估算。','context'),Q(1,'Can people be of one mind while strongly disagreeing?','No; the phrase means they share an opinion.','Yes; it means they never discuss a topic.','Yes; it means one person is absent.','短语要求意见一致。','distinction')]);
P('of that kind','A compositional phrase: of links an item to a category, while that kind points back to a type already mentioned.',C('of that kind.s1','通用','We have several repair kits of that kind, with waterproof tape and a compact hand pump.','我们有几套那种维修包，里面有防水胶带和小型手泵。','We have several repair kits / of that kind / with waterproof tape and a compact hand pump.','of that kind 表示属于前文提到的同一类型。','that kind 回指已知的维修包类型。'),M('She requested a repair kit of that kind before anyone had described or shown any type of kit.','After seeing the waterproof kit, she requested another repair kit of that kind.','that kind 需要可回指的类别，不能无前文地指某一类。','context'),[Q(1,'What does of that kind refer to?','A repair-kit type already identified.','Any object in the room.','A type of weather never mentioned.','of that kind.s1 回指已提到的类型。'),Q(1,'Which phrase has a similar function?','of the same type','at a later date','in a different place','两者都表示属于同一种类。','meaning'),Q(1,'What was inside the kits?','Waterproof tape and a hand pump.','A kettle and a poem.','A telescope and an octopus.','例句列出维修包里的物品。','context'),Q(1,'Why is that kind useful here?','It refers back to a type already described.','It gives the exact number of kits.','It changes repair into a verb.','that 回指已知类别。','grammar')]);
P('of which','A relative construction: of + which introduces information about a previously mentioned thing, often after a number or quantity.',C('of which.s1','语法','The archive received twelve maps, three of which showed the coastline before the harbor was built.','档案馆收到十二张地图，其中三张展示了港口建成前的海岸线。','The archive received twelve maps / three of which / showed the coastline / before the harbor was built.','of which 是关系结构；three of which 指前述地图中的三张。','which 回指十二张地图。'),M('The report wrote “three of which maps” instead of placing of which after the noun phrase.','The report wrote “three of the maps, three of which showed the old coastline.”','of which 后接谓语，不能再重复写被指代的名词 maps。','grammar'),[Q(1,'How many maps showed the older coastline?','Three.','Twelve thousand.','None; the archive had no maps.','of which.s1 中 three 指十二张地图中的三张。','number'),Q(1,'What does which refer to?','The maps.','The archive.','The harbor workers.','which 回指 maps。','grammar'),Q(1,'Choose the correct phrase.','Ten prints, two of which are signed.','Ten prints, two of which prints are signed.','Ten prints, which of two are signed.','two of which 是正确的部分关系结构。','grammar'),Q(1,'What information follows of which here?','A detail about three maps.','A new unrelated topic.','A verb with no subject.','从句补充说明其中三张地图。','context')]);
P('of whom','A relative construction: of + whom refers to people already mentioned, usually after a number or quantifier.',C('of whom.s1','语法','The panel interviewed six applicants, two of whom had previously worked on coastal restoration.','评审组面试了六名申请人，其中两人以前从事过海岸修复。','The panel interviewed six applicants / two of whom / had previously worked / on coastal restoration.','of whom 指前述人群中的人；two of whom 即其中两人。','whom 回指六名申请人。'),M('The letter said “two of whom applicants had experience,” repeating the noun after the relative phrase.','The letter said “two of the applicants had experience,” or “two of whom had experience.”','of whom 后直接接谓语，不能再重复写 applicants。','grammar'),[Q(1,'How many applicants had restoration experience?','Two.','All six were said to have it.','No applicants were interviewed.','of whom.s1 中 two 指六名申请人中的两人。','number'),Q(1,'Whom does whom refer to?','The applicants.','The panel.','The coastline.','whom 指前文提到的人。','grammar'),Q(1,'Which sentence is correct?','Several guests, some of whom arrived early, waited outside.','Several guests, some of whom guests arrived early, waited outside.','Several guests, some who of arrived early, waited outside.','结构为 some of whom + 谓语。','grammar'),Q(1,'Why is whom used rather than which?','It refers to people.','It refers to the number six.','It refers to an inanimate coast.','whom 用来指人。','distinction')]);
P('off','From Old English of “away, away from,” related to of; senses include movement away, separation or proximity, switched off, time away from duty, and a discount.',[C('off.s1','通用','The lid slipped off the jar when the child lifted it by the rim.','孩子抓着罐沿提起时，盖子从罐子上滑落了。','The lid slipped off the jar / when the child lifted it / by the rim.','off.s1 表示离开表面或原来位置。','盖子从罐子上脱开。'),C('off.s2','通用','The island lies just off the southern coast, a short ferry ride from the mainland.','这座岛就在南岸附近，乘渡船离大陆不远。','The island lies just off the southern coast / a short ferry ride / from the mainland.','off.s2 可表示离开某处或离某地不远。','just off the coast 表示近海。'),C('off.s3','通用','Please make sure the heater is off before you leave the cabin for the night.','晚上离开小屋前，请确认取暖器已经关闭。','Please make sure the heater is off / before you leave the cabin / for the night.','off.s3 作形容词表示关闭或停止运转。','取暖器关闭后不再运行。'),C('off.s4','工作','The nurse is off tomorrow, so another colleague will cover the morning shift.','护士明天休息，因此另一位同事会顶替早班。','The nurse is off tomorrow / so another colleague / will cover the morning shift.','off.s4 表示不上班或不值班。','同事代班说明护士不当班。'),C('off.s5','商业','The shop took ten dollars off the price when the customer bought the display model.','顾客买展示样机时，商店从售价中减了十美元。','The shop took ten dollars off the price / when the customer bought the display model.','off.s5 可表示从价格中扣除或降价。','十美元从售价中减去。')],M('The sign said the heater was off while its burner remained lit and it continued heating the room.','The sign said the heater was on while its burner remained lit and it continued heating the room.','设备仍在加热时不能说它已关闭。','distinction'),[Q(1,'Where did the lid move?','Away from the jar.','Into the jar’s contents.','Toward the child’s hand only.','off.s1 表示从表面脱离。'),Q(2,'What does just off the coast mean?','Near the coast, out in the sea.','Far inland.','Below the seabed.','off.s2 表示离岸不远。'),Q(3,'What should be true before leaving the cabin?','The heater should be switched off.','The heater should keep running.','The heater should be discounted.','off.s3 表示设备关闭。'),Q(5,'What did the shop do to the price?','Reduced it by ten dollars.','Added ten dollars.','Moved the product off the shelf.','off.s5 表示从售价中减去金额。','meaning')]);

P('off target','A phrase built from off “away from” + target; off target describes a shot that misses the intended mark or a result that deviates from its goal.',C('off target.s1','体育','Her first arrow landed off target, striking the straw beside the painted red circle.','她的第一支箭没有命中靶心，射在红圈旁的草靶上。','Her first arrow landed off target / striking the straw / beside the painted red circle.','off target 表示没有打中目标，也可指偏离既定方向。','箭落在靶纸的红圈之外。'),M('The scoreboard marked the shot off target even though the arrow hit the center of the red circle.','The scoreboard marked the shot on target because the arrow hit the center of the red circle.','命中靶心应是 on target；off target 表示偏离目标。','distinction'),[Q(1,'Where did the arrow land?','Beside the red circle.','In the center of the red circle.','Behind the archer.','off target.s1 表示没有命中目标。'),Q(1,'Which result is off target?','A dart lands outside the bullseye.','A ball hits the center of the goal.','An arrow strikes the marked circle.','脱靶意味着偏离靶心。','meaning'),Q(1,'What is the opposite of off target in this sports context?','on target','at odds','off duty','命中目标可说 on target。','confusable'),Q(1,'Why was the first arrow off target?','It missed the painted red circle.','The archer scored a perfect center hit.','The target had not been painted.','例句明确箭落在红圈旁。','context')]);
P('off-campus','A compound of off + campus; it functions as an adverb meaning away from campus and as an adjective for something located there.',[C('off-campus.s1','教育','The graduate students rented an apartment off-campus because the university dormitories were full.','由于大学宿舍已住满，研究生们在校外租了一套公寓。','The graduate students rented an apartment off-campus / because the university dormitories were full.','off-campus.s1 作副词，表示在校园之外。','学生在校外租住公寓。'),C('off-campus.s2','教育','The department arranged an off-campus seminar at a marine laboratory near the harbor.','系里在港口附近的海洋实验室安排了一场校外研讨会。','The department arranged an off-campus seminar / at a marine laboratory / near the harbor.','off-campus.s2 作形容词，修饰校外举办或设置的事物。','研讨会地点不在大学校园内。')],M('The notice called a lecture in the university’s main hall off-campus even though it took place inside the campus.','The notice called the seminar at the harbor laboratory off-campus.','主校区内的活动不是 off-campus；该词表示校园外。','distinction'),[Q(1,'Why did the students rent an apartment off-campus?','The dormitories were full.','The harbor laboratory was closed.','They wanted to live inside the dormitory.','off-campus.s1 指校园之外。'),Q(2,'Where was the off-campus seminar held?','At a marine laboratory near the harbor.','In the university’s main hall.','Inside the dormitory kitchen.','off-campus.s2 修饰校外举办的研讨会。'),Q(1,'Which sentence uses off-campus as an adverb?','She lives off-campus during the semester.','The off-campus seminar starts at noon.','The campus is off-campus.','这里 off-campus 说明住在哪里。','grammar'),Q(2,'Which noun can off-campus modify in the example?','seminar','harbor water only','graduate students’ age','形容词用法修饰 seminar。','grammar')]);
P('off-limits','A compound phrase from off + limits; it means forbidden or inaccessible to a particular person or group.',C('off-limits.s1','通用','The archive room is off-limits to visitors while staff repair the climate-control system.','工作人员修理温控系统期间，档案室禁止访客进入。','The archive room is off-limits to visitors / while staff repair / the climate-control system.','off-limits 表示某地点或话题对特定人禁止进入或触及。','to visitors 指明被禁止进入的人群。'),M('The sign said the archive room was off-limits to visitors and then invited them to walk inside unsupervised.','The sign said the archive room was off-limits to visitors until repairs were complete.','off-limits 表示禁止进入，不能同时授权访客随意进入。','context'),[Q(1,'Who could not enter the archive room?','Visitors.','The repair staff.','The climate-control system.','off-limits.s1 禁止访客进入。'),Q(1,'When will the restriction last?','While staff repair the system.','Only after the system has been repaired for years.','Until the archive closes permanently.','维修期间房间被限制进入。'),Q(1,'Which phrase is closest to off-limits?','forbidden to enter','open to everyone','temporarily discounted','off-limits means forbidden or restricted.','meaning'),Q(1,'What does “to visitors” identify?','The group restricted from entry.','The room’s owner.','The repair schedule.','to visitors marks the people to whom access is barred.','grammar')]);
P('offal','From Middle English offal, originally “that which falls off” during butchering, from off + fall; it denotes edible internal organs of an animal.',C('offal.s1','饮食','The butcher set aside the liver and heart as offal for a customer who planned to cook them slowly.','屠夫把肝和心脏作为动物内脏留给一位打算慢炖的顾客。','The butcher set aside the liver and heart / as offal / for a customer / who planned to cook them slowly.','offal 指用作食物的动物内脏。','肝脏和心脏是供食用的内脏。','word-formation'),M('The menu called a boneless chicken breast offal even though it contained no internal organs.','The menu described the liver and heart stew as offal.','offal 指内脏，不是普通的肌肉肉块。','distinction'),[Q(1,'Which cuts were set aside as offal?','The liver and heart.','A boneless breast and wing tip.','A loaf of bread.','offal.s1 指可食用动物内脏。'),Q(1,'Which dish could contain offal?','A stew made with liver.','A salad made only with lettuce.','A glass of water.','肝脏属于内脏食材。','meaning'),Q(1,'What was the customer planning to do with the offal?','Cook it slowly.','Use it to repair the butcher’s door.','Feed it to a projector.','例句说明顾客要慢炖内脏。','context'),Q(1,'How did offal historically relate to butchering?','It referred to parts that fell off during butchering.','It meant a butcher’s official title.','It was a Latin word for a cooking pot.','offal 最初指屠宰时切下的部分。','word-formation')]);
P('offcut','A compound of off + cut; an offcut is a piece left over after the main material has been cut.',C('offcut.s1','工业','The cabinetmaker saved each oak offcut for small repairs instead of throwing the pieces away.','橱柜工匠把每块橡木边角料都留下来做小修补，而不是扔掉。','The cabinetmaker saved each oak offcut / for small repairs / instead of throwing the pieces away.','offcut 指切割主要材料后剩下的边角料。','橡木小块是裁切后留下的余料。'),M('The carpenter labeled the uncut full-length plank an offcut before making any cut in it.','The carpenter labeled the short piece left after cutting the plank an offcut.','offcut 是切割后剩余的小块，不是尚未裁切的整块木板。','word-choice'),[Q(1,'What did the cabinetmaker save?','Small leftover oak pieces.','A whole tree.','A finished glass window.','offcut.s1 指裁切后留下的材料。'),Q(1,'Why keep the offcuts?','They could be used for small repairs.','They were full-length untouched planks.','They were too large to store.','边角料可用于小修补。','context'),Q(1,'Which item is an offcut?','A short strip left after trimming a board.','A new uncut board.','A tool used to measure a board.','切下后留下的短条符合定义。','meaning'),Q(1,'What does off add to cut in offcut?','The idea of a leftover piece separated by cutting.','The idea of cutting something twice.','The idea of cutting toward a target.','复合词表示切下来的剩料。','word-formation')]);
P('offence','From Old French offence and Latin offensa “a striking against, injury,” from offendere; in English it can mean a crime or an insult that causes hurt.',[C('offence.s1','法律','Parking in the marked emergency lane is a traffic offence, even when the road appears empty.','即使道路看起来空着，把车停在标出的紧急车道上仍是交通违法行为。','Parking in the marked emergency lane / is a traffic offence / even when the road appears empty.','offence.s1 指违法行为或罪行。','违规停车仍属于交通违法。'),C('offence.s1','社交','She took offence at the joke because it mocked the accent she had worked hard to preserve.','她觉得那个笑话冒犯了自己，因为它嘲笑了她努力保留的口音。','She took offence at the joke / because it mocked the accent / she had worked hard to preserve.','offence.s1 指冒犯或伤害感情的言行。','嘲笑口音使她感到受辱。')],M('The officer said the driver committed no offence by deliberately parking in the emergency lane against the posted law.','The officer said the driver committed an offence by parking in the emergency lane.','违反明示交通规则的行为构成违法，而非“没有违法”。','meaning'),[Q(1,'What kind of offence was described?','A traffic violation.','A poem about a road.','A polite compliment.','offence.s1 指违法行为。'),Q(1,'Why did she take offence?','The joke mocked her accent.','The joke praised her work.','The speaker asked for directions.','offence.s1 指伤感情或冒犯。'),Q(1,'Which spelling is common in British English?','offence','offince','offencee','offence is the British spelling; offense is the usual US form.','spelling'),Q(1,'What two broad senses does offence have here?','A crime and an insult.','A job and a hobby.','A smell and a color.','该词既可指罪行，也可指冒犯。','distinction')]);
P('offend','From Old French ofendre, from Latin offendere “strike against, hurt”; it can upset someone, break a law, or go against a custom or principle.',[C('offend.s1','通用','The host worried that asking about the guest’s salary might offend her, so he changed the subject.','主人担心询问客人的薪水会冒犯她，于是换了话题。','The host worried / that asking about the guest’s salary might offend her / so he changed the subject.','offend.s1 指使人感到受辱、难过或生气。','主人预想到这个问题可能伤害客人感情。'),C('offend.s2','法律','The company was fined after it offended the safety regulations by disabling the alarm system.','公司因关闭警报系统、违反安全条例而被罚款。','The company was fined / after it offended the safety regulations / by disabling the alarm system.','offend.s2 指违反法律或规章。','关闭警报违反了安全条例。'),C('offend.s3','书面','The design may offend local custom because it places shoes on the table during the ceremony.','这个设计可能有悖当地习俗，因为它让人们在仪式中把鞋子放在桌上。','The design may offend local custom / because it places shoes on the table / during the ceremony.','offend.s3 可指违背习俗、品味或原则。','设计与当地礼仪相冲突。')],M('The company offended no safety rule by disabling the required alarm and was fined for obeying every regulation.','The company offended safety rules by disabling the required alarm and was fined.','关闭必需警报违反规定，不能说是遵守规定。','distinction'),[Q(1,'Why did the host change the subject?','He feared the salary question might upset the guest.','He wanted to ask the guest to disable an alarm.','He had already left the room.','offend.s1 表示冒犯他人。'),Q(2,'Why was the company fined?','It violated safety regulations.','It asked about a guest’s salary.','It preserved a local custom.','offend.s2 表示违反规定。'),Q(3,'What might offend local custom?','Putting shoes on a table during a ceremony.','Following the ceremony’s normal rules.','Asking where the table was made.','offend.s3 指有悖习俗。'),Q(1,'Which sentence uses offend to mean “upset someone”?','His blunt remark offended the visitor.','The firm offended a safety regulation.','The design offended local custom.','第一句中 offend 的宾语是 visitor，表示伤害其感情。','distinction')]);
P('offensive','From offence/offend + -ive; as an adjective it means insulting or likely to upset, and as a noun it can mean a planned attack.',[C('offensive.s1','社交','The museum removed the offensive caption after visitors explained that it mocked a community’s painful history.','游客指出那条说明嘲弄了一个群体痛苦的历史后，博物馆将其撤下。','The museum removed the offensive caption / after visitors explained / that it mocked a community’s painful history.','offensive.s1 作形容词，表示冒犯或可能伤害感情。','说明文字嘲笑了群体经历，因此令人受伤。'),C('offensive.s2','军事','The brigade began its offensive at dawn, advancing toward the ridge after weeks of preparation.','旅部队在黎明发动攻势，经过数周准备后向山脊推进。','The brigade began its offensive at dawn / advancing toward the ridge / after weeks of preparation.','offensive.s2 作名词，指军队或团队有计划的进攻。','部队发动军事攻势。')],M('The caption was called offensive because every visitor found it respectful and harmless.','The caption was called offensive because it mocked a community’s painful history.','冒犯性内容会伤害或侮辱他人，不是尊重而无害。','distinction'),[Q(1,'Why did the museum remove the caption?','It mocked a community’s painful history.','It described the ridge’s location.','It announced the brigade’s schedule.','offensive.s1 指可能伤害感情的内容。'),Q(2,'What did the brigade begin at dawn?','A planned attack.','A museum caption.','A staff meeting.','offensive.s2 作名词表示攻势。'),Q(1,'Which meaning fits “offensive remark”?','Insulting or likely to upset.','A military attack.','A pleasant invitation.','此处 offensive 是形容词义。','distinction'),Q(2,'Which clue signals offensive is a noun in the brigade sentence?','It follows “began its” and names an operation.','It comes before a caption.','It describes a visitor’s feelings.','“its offensive”指一场军事攻势。','grammar')]);
P('offer','From Old French offrir, from Latin offerre “present, bring before,” from ob- “toward” + ferre “carry”; senses include giving, volunteering, bidding, a proposal, and a special price.',[C('offer.s1','通用','The neighbor offered us a spare umbrella when rain began on the walk home.','回家路上开始下雨时，邻居主动把一把备用伞给了我们。','The neighbor offered us a spare umbrella / when rain began / on the walk home.','offer.s1 作动词，表示提出愿意给予某物。','邻居愿意把备用伞给我们。'),C('offer.s2','通用','After the storm, two volunteers offered to clear branches from the blocked footpath.','暴风雨过后，两名志愿者主动提出清理被堵人行道上的树枝。','After the storm / two volunteers offered to clear branches / from the blocked footpath.','offer.s2 表示主动提出做某事，常接 to do。','志愿者提出帮忙清理。'),C('offer.s3','商业','The buyer offered $240,000 for the small house after the inspection.','看房检查后，买家为这栋小房子出价24万美元。','The buyer offered $240,000 / for the small house / after the inspection.','offer.s3 表示对商品或房产出价。','金额是买家愿意支付的价格。'),C('offer.s4','通用','The committee rejected an offer to extend the deadline by two weeks.','委员会拒绝了将期限延长两周的提议。','The committee rejected an offer / to extend the deadline / by two weeks.','offer.s4 作名词，表示提议或愿意提供的事。','名词 offer 引出延期提议。'),C('offer.s5','商业','The store’s weekend offer gave customers 20 percent off selected lamps.','商店的周末优惠让顾客购买部分灯具时享受八折。','The store’s weekend offer / gave customers 20 percent off / selected lamps.','offer.s5 作名词可指限时特价或优惠。','折扣是商店的促销优惠。')],M('The buyer offered $240,000 but the seller recorded it as a discount the store gave every customer.','The buyer offered $240,000 as a bid for the house; the store’s discount was a separate offer.','出价和商店促销优惠是不同的 offer 用法。','distinction'),[Q(1,'What did the neighbor offer?','A spare umbrella.','A house for sale.','A two-week deadline.','offer.s1 表示愿意给予物品。'),Q(2,'What did the volunteers offer to do?','Clear branches from the path.','Buy the small house.','Give customers a discount.','offer to do 表示主动提出做事。'),Q(3,'How much did the buyer offer for the house?','$240,000.','$24,000.','20 percent off.','offer.s3 是买家的出价金额。','number'),Q(5,'What was the store’s weekend offer?','A 20 percent discount on selected lamps.','A bid on a house.','A volunteer cleanup.','offer.s5 指商店优惠。','distinction')]);
P('offering','From offer + -ing, used as a noun for something presented or made available; historically it can be a gift or sacrifice presented to a deity.',C('offering.s1','宗教','The villagers placed an offering of rice and flowers at the shrine during the harvest ceremony.','收获仪式上，村民把米和鲜花作为供品放在神龛前。','The villagers placed an offering of rice and flowers / at the shrine / during the harvest ceremony.','offering 指奉献物或供品，也可泛指向人提供的东西。','米和鲜花被献到神龛前。'),M('The guide called the untouched rice an offering even though no one had presented it to the shrine or anyone else.','The guide called the rice and flowers placed at the shrine an offering.','offering 表示被献出或提供的东西，不是无人给予的物品。','meaning'),[Q(1,'What did the villagers place at the shrine?','Rice and flowers.','A price bid for a house.','A museum caption.','offering.s1 指献上的供品。'),Q(1,'What does an offering usually involve?','Giving or presenting something.','Withholding every item.','Taking control of a building.','offering 与给予或献上有关。','meaning'),Q(1,'Which is an offering in a religious ceremony?','A bowl of fruit placed before an altar.','A hidden empty bowl never presented.','A price tag left in a store.','献在祭坛前的水果是供品。','context'),Q(1,'How is offering formed?','offer + -ing','off + comparative -er','offence + plural -s','-ing forms the noun offering from offer.','word-formation')]);
P('offhand','From off + hand, originally suggesting something done without preparation; as an adverb or adjective it describes an unplanned, casual, or brusque remark.',C('offhand.s1','性格','Asked for the exact date, the curator gave an offhand estimate and promised to check the archive later.','被问到确切日期时，馆长随口估了一个时间，并答应稍后查阅档案。','Asked for the exact date / the curator gave an offhand estimate / and promised to check the archive later.','offhand 表示未经准备、随口说出的；也可指态度冷淡。','估计不是查档后给出的正式答案。'),M('The curator read a carefully researched, fully documented report aloud and called it an offhand estimate.','The curator gave a quick offhand estimate before checking the archive.','offhand 表示未经充分准备或随口说，不适合精心查证的报告。','distinction'),[Q(1,'Was the curator’s estimate carefully verified at that moment?','No; it was given casually before checking.','Yes; the archive had already been fully reviewed.','Yes; it was a final legal ruling.','offhand.s1 描述随口给出的估计。'),Q(1,'Which response sounds offhand?','“I’d guess around noon, but I’ll confirm.”','A signed report with source notes.','A precise result copied from the archive.','临时猜测并承诺核实是随口回答。','context'),Q(1,'Which part of speech can offhand be?','Adverb or adjective.','Only a plural noun.','Only a past-tense verb.','source sense labels it adverb/adjective.','grammar'),Q(1,'What does offhand suggest about preparation?','Little or none.','Several months of research.','A formal approval process.','offhand 常表示未经准备或即兴。','meaning')]);
P('office','From Old French office, from Latin officium “service, duty”; senses include a place for work, a professional service location, an official post, and a doctor’s room or government department.',[C('office.s1','工作','The editor returned to her office after lunch and reviewed the final pages with the design team.','午饭后，编辑回到办公室，与设计团队审阅最后几页。','The editor returned to her office / after lunch / and reviewed the final pages / with the design team.','office.s1 指人们办公的房间或建筑。','编辑在办公室审稿。'),C('office.s2','商业','The family visited a solicitor’s office to ask how the property transfer should be filed.','这家人去了律师事务所，询问房产转让该如何备案。','The family visited a solicitor’s office / to ask / how the property transfer / should be filed.','office.s2 指提供专业服务的办事处或事务所。','律师事务所为客户提供法律服务。'),C('office.s3','政治','She was elected to office after promising to expand rural clinics and public transit.','她承诺扩建乡村诊所和公共交通后当选公职。','She was elected to office / after promising / to expand rural clinics and public transit.','office.s3 指重要的正式职位或公职。','当选后担任公共职位。'),C('office.s4','通用','The doctor’s office called to confirm the patient’s appointment for Tuesday morning.','医生诊所打电话确认患者周二上午的预约。','The doctor’s office called / to confirm the patient’s appointment / for Tuesday morning.','office.s4 在美式用法中可指医生诊所，也可指政府机关。','医生诊所联系患者确认预约。')],M('The report said the editor reviewed pages at her office but defined office only as an elected political position.','The report said the editor reviewed pages in her work room, while office can also mean a public post.','office 可指工作场所，也可指公职，需根据语境判断。','distinction'),[Q(1,'Where did the editor review the pages?','In her work room.','At the solicitor’s office.','In an elected political post.','office.s1 指办公地点。'),Q(2,'What service did the solicitor’s office provide?','Legal advice.','Medical treatment.','Public transit.','office.s2 指律师事务所。'),Q(3,'What did she win through election?','An official position.','A room to review pages.','A property transfer document.','office.s3 是公职义。'),Q(4,'Which office called to confirm the appointment?','The doctor’s clinic.','The editor’s design room.','The election office only.','office.s4 可指医生诊所。','distinction')]);
P('officeholder','From office + holder, a transparent compound for a person who holds an official position.',C('officeholder.s1','政治','Every officeholder on the committee disclosed financial interests before voting on the new contract.','委员会中的每位任职者都在就新合同投票前披露了财务利益。','Every officeholder on the committee / disclosed financial interests / before voting / on the new contract.','officeholder 指担任某个正式职位的人。','委员会成员在正式职务上参与投票。'),M('The report named the empty committee chair an officeholder although no person held the position.','The report named the elected committee member an officeholder.','officeholder 指人，不指空缺职位或椅子。','word-choice'),[Q(1,'What did each officeholder disclose?','Financial interests.','The building’s paint color.','A poem about a river.','officeholder.s1 指任职者。'),Q(1,'When did they disclose the interests?','Before voting on the contract.','After the committee had dissolved years earlier.','Before being appointed to any role.','例句说明披露发生在投票前。','context'),Q(1,'Who is an officeholder?','A person holding an official position.','An empty chair in a meeting room.','A visitor without a role.','officeholder 指担任正式职位的人。','meaning'),Q(1,'How is officeholder formed?','office + holder','offence + -less','official + comparative -er','The compound combines office and holder.','word-formation')]);
P('officer','From Old French officier, from Latin officiarius “official”; senses include a military commander, a police officer, and an official in government or a company.',[C('officer.s1','军事','The naval officer checked the crew’s safety briefing before the ship left the harbor.','军官在船只离开港口前检查了船员的安全简报。','The naval officer checked the crew’s safety briefing / before the ship left the harbor.','officer.s1 指军队中负责指挥或管理的军官。','海军军官负责检查船员安全程序。'),C('officer.s2','法律','A police officer directed traffic around the blocked intersection while crews cleared the fallen tree.','清理倒树期间，一名警察在被堵的十字路口指挥交通。','A police officer directed traffic / around the blocked intersection / while crews cleared the fallen tree.','officer.s2 指警察或警官。','警察现场维持交通秩序。'),C('officer.s3','工作','The company’s compliance officer reviewed the new reporting rules with department heads.','公司的合规官与各部门负责人一起审阅了新的报告规定。','The company’s compliance officer reviewed the new reporting rules / with department heads.','officer.s3 指政府或公司中担任正式职务的官员。','合规官在公司履行正式职责。')],M('The newspaper called a civilian traffic volunteer a naval officer even though she held no military rank.','The newspaper called the ship’s commissioned commander a naval officer.','军官身份取决于军队职务或军衔，普通志愿者不是军官。','distinction'),[Q(1,'What did the naval officer check?','The crew’s safety briefing.','The intersection’s traffic lights.','The company’s filing rules.','officer.s1 指船上军官。'),Q(2,'What did the police officer do?','Directed traffic.','Reviewed corporate reports.','Commanded the naval ship.','officer.s2 指警察。'),Q(3,'What was the compliance officer reviewing?','Reporting rules.','A harbor tide chart.','A driver’s license.','officer.s3 是公司职务。'),Q(2,'Which title most clearly means a police officer?','A traffic officer at an intersection.','A naval commander at sea.','A company compliance manager.','语境“路口指挥交通”指警察。','context')]);
P('officers','Plural of officer; the source entry uses it collectively for police officers or other people in positions of authority.',C('officers.s1','职业','The officers at the station answered residents’ questions and directed them to the right department.','警局里的警官回答居民的问题，并指引他们去相应部门。','The officers at the station / answered residents’ questions / and directed them / to the right department.','officers 是 officer 的复数，常指警官或其他身居职务的人。','station 和答疑服务在此指警局警官。','plural'),M('The report used officers for one police officer and noted that the word was singular.','The report used officer for one person and officers for more than one.','officers 是复数形式，单数为 officer。','plural'),[Q(1,'Where were the officers working?','At the station.','At a marine laboratory.','In an empty classroom.','officers.s1 指警局中的警官。'),Q(1,'What did the officers do for residents?','Answered questions and gave directions.','Sold them hotel rooms.','Measured ocean salinity.','例句说明警官为居民提供帮助。'),Q(1,'What is the singular of officers?','officer','officery','officess','officers is the plural of officer.','plural'),Q(1,'Which sentence has the correct plural?','Two officers spoke with the residents.','Two officer spoke with the residents.','One officers spoke with the residents.','复数 two 后用 officers。','grammar')]);
P('official','From Latin officialis “of duty or office,” from officium “service, duty”; as an adjective it means authorized or connected with public duties, and as a noun it means an officeholder.',[C('official.s1','通用','The agency posted the official schedule after the director approved the final dates and locations.','主任批准最终日期和地点后，机构发布了正式日程。','The agency posted the official schedule / after the director approved / the final dates and locations.','official.s1 指经权威机构认可或正式发布的。','机构批准后公布的日程属于正式版本。'),C('official.s2','工作','The minister attended the opening in her official capacity, representing the department rather than her family.','部长以公务身份出席开幕式，代表的是部门而不是家人。','The minister attended the opening / in her official capacity / representing the department / rather than her family.','official.s2 表示与公职或公务职责有关。','她以部长身份代表部门出席。'),C('official.s3','政治','An election official explained how to request a replacement ballot before polls closed.','一名选举官员解释了如何在投票站关闭前申请补发选票。','An election official explained / how to request a replacement ballot / before polls closed.','official.s3 作名词，指在组织或政府机构中有职权的人员。','选举官员提供投票程序说明。')],M('The agency called an unapproved rumor its official schedule before the director had checked it.','The agency called the director-approved schedule official after confirming its dates.','未经授权的传闻不能称为正式日程。','distinction'),[Q(1,'Who approved the official schedule?','The director.','The minister’s family.','A visitor at the polling place.','official.s1 表示经授权确认。'),Q(2,'In what capacity did the minister attend?','As a representative of the department.','As a private family guest.','As an election ballot.','official.s2 与公务身份有关。'),Q(3,'What did the election official explain?','How to request a replacement ballot.','How to publish a theater poem.','How to measure an ocean.','official.s3 是负责投票事务的官员。'),Q(1,'Which document is official?','A schedule approved and posted by the agency.','An unverified message from an unknown sender.','A draft no authority has approved.','正式文件经权威机构认可。','meaning')]);
P('officially','From official + -ly; it means with formal authorization or according to the public or formally stated account.',C('officially.s1','通用','The bridge officially reopened on Monday after inspectors signed the safety certificate.','检查员签署安全证书后，这座桥于周一正式重新开放。','The bridge officially reopened / on Monday / after inspectors signed the safety certificate.','officially 表示经正式批准或按公开正式说法。','签署证书使重新开放具有正式效力。','word-formation'),M('The bridge was officially open even though the authority had not approved it and the gates remained locked.','The bridge was not officially open until the authority approved it and unlocked the gates.','正式开放需要授权，门锁着且未批准时不能说 officially open。','distinction'),[Q(1,'When did the bridge officially reopen?','On Monday.','Before inspectors arrived years earlier.','Only after it was demolished.','officially.s1 表示正式开放。'),Q(1,'What made the reopening official?','Inspectors signed the safety certificate.','A passerby guessed the bridge was safe.','The weather became sunny.','正式批准来自检查证书。','context'),Q(1,'Which phrase is closest to officially?','formally','accidentally','secretly without approval','officially means with formal authorization.','meaning'),Q(1,'How is officially formed?','official + -ly','office + plural -s','off + past-tense -ed','-ly forms the adverb officially.','word-formation')]);
P('officiate','From Latin officiari “perform a duty,” from officium “service”; to officiate is to conduct a ceremony or serve as the referee of a match.',C('officiate.s1','体育','A retired international referee agreed to officiate the final after the original official became ill.','原裁判生病后，一名退休的国际裁判同意执裁决赛。','A retired international referee agreed / to officiate the final / after the original official became ill.','officiate 指主持仪式或担任比赛裁判。','句中裁判负责执裁比赛。'),M('The match report said the referee officiated the game but made no decisions and never watched play.','The match report said the referee officiated the game and enforced its rules.','裁判执裁比赛意味着监督并执行比赛规则。','meaning'),[Q(1,'Who officiated the final?','A retired international referee.','A museum visitor.','A player who left before kickoff.','officiate.s1 指担任比赛裁判。'),Q(1,'What does a referee do when officiating?','Enforces the rules of a match.','Writes an ode to the stadium.','Sets the hotel’s occupancy rate.','执裁包括监督比赛规则。'),Q(1,'Which event could someone officiate?','A wedding ceremony.','A private nap.','A weather forecast in the past.','officiate 也可指主持仪式。','meaning'),Q(1,'Why was a replacement referee needed?','The original official became ill.','The final had no rules.','The bridge reopened.','例句说明原裁判生病。','context')]);
P('officious','From Latin officiosus “dutiful, obliging,” from officium “duty”; the modern adjective is usually negative, describing intrusive eagerness to manage others.',C('officious.s1','通用','An officious neighbor kept rearranging the volunteers’ tools and issuing orders although the crew leader had not asked for help.','一位爱管闲事的邻居不断重新摆放志愿者的工具并发号施令，尽管队长并未请求帮忙。','An officious neighbor / kept rearranging the volunteers’ tools / and issuing orders / although the crew leader had not asked for help.','officious 指过分热心插手、好管闲事。','邻居擅自指挥并干预他人工作。'),M('The officious assistant quietly completed the assigned task and waited without directing anyone.','The officious assistant repeatedly interrupted coworkers to impose unwanted instructions.','主动插手和强加指令才符合 officious 的贬义。','distinction'),[Q(1,'What made the neighbor officious?','He rearranged tools and gave unrequested orders.','He followed the crew leader’s instructions quietly.','He left the volunteers alone.','officious.s1 指过分干预他人。'),Q(1,'Which behavior is officious?','A visitor keeps enforcing rules no one asked them to enforce.','A helper follows a requested task.','A referee applies the game rules.','未经请求而热衷指挥是 officious。','meaning'),Q(1,'Is officious usually positive or negative?','Negative; it suggests intrusive helpfulness.','Positive; it means officially elected.','Neutral; it means taking a day off.','现代 officious 通常含贬义。','register'),Q(1,'Why was the crew leader’s request relevant?','The neighbor interfered without being asked.','The leader had ordered the neighbor to rearrange the tools.','The volunteers had no tools.','未经请求的插手体现好管闲事。','context')]);
P('offset','From off + set, with roots in the sense of setting one thing against another; offset can mean counteract, a compensating factor, a displacement, or a printing method.',[C('offset.s1','经济','The savings from the efficient boiler helped offset the building’s higher insulation costs over time.','高效锅炉带来的节省有助于逐步抵消建筑较高的保温成本。','The savings from the efficient boiler / helped offset / the building’s higher insulation costs / over time.','offset.s1 作动词，表示抵消或弥补相反影响。','节省的费用减轻了额外成本。'),C('offset.s2','通用','A small grant served as an offset for the extra travel expenses the research team had incurred.','一笔小额补助抵补了研究团队额外发生的差旅开支。','A small grant served as an offset / for the extra travel expenses / the research team had incurred.','offset.s2 作名词，指补偿物或抵消因素。','补助弥补额外支出。'),C('offset.s3','印刷','The publisher chose offset printing for the large run because it produced consistent color across thousands of copies.','出版商为大批量印刷选择胶印，因为数千份印品的颜色一致。','The publisher chose offset printing / for the large run / because it produced consistent color / across thousands of copies.','offset.s3 作名词可指偏移量，也可指利用滚筒转印的胶印法。','例句中的 offset printing 指胶印技术。')],M('The grant increased the team’s net travel cost and therefore offset none of its expenses.','The grant reduced the team’s net travel cost by offsetting part of its expenses.','抵补费用会降低净成本，而非增加净成本。','distinction'),[Q(1,'What did the boiler savings do?','They helped counterbalance higher insulation costs.','They increased those costs.','They printed the building plans.','offset.s1 表示抵消负面影响或成本。'),Q(2,'What served as an offset for travel expenses?','A small grant.','The boiler itself.','A printing roller.','offset.s2 指起补偿作用的补助。'),Q(3,'Why choose offset printing?','It kept colors consistent across many copies.','It reduced the number of pages to zero.','It measured travel expenses.','offset.s3 指胶印技术。','context'),Q(1,'Which sentence uses offset as a verb?','The tax credit helped offset the repair bill.','The printer used offset for a large run.','A grant was an offset for travel costs.','第一句 offset 作动词表示抵消。','grammar')]);

P('offshoot','From off + shoot, originally a shoot or branch growing outward; it also means a secondary branch of a family, organization, or development.',C('offshoot.s1','通用','The neighborhood food cooperative began as an offshoot of a larger citywide network.','这个社区食品合作社起初是全市大型网络的一个分支。','The neighborhood food cooperative / began as an offshoot / of a larger citywide network.','offshoot 指植物、家族或组织的旁支，也可指某发展的派生事物。','社区合作社从更大的组织网络中分出。'),M('The cooperative was called an offshoot even though it had no connection to or development from the citywide network.','The cooperative was called an offshoot because it developed from the citywide network.','offshoot 表示由某事发展或分出，需有来源联系。','distinction'),[Q(1,'What was the cooperative an offshoot of?','A larger citywide network.','A marine laboratory.','A family’s dinner table.','offshoot.s1 指组织的派生分支。'),Q(1,'Which is an offshoot of a plant?','A side branch growing from its main stem.','A seed never planted or sprouted.','A machine with no plant parts.','该词原义与长出的枝条有关。','word-formation'),Q(1,'Which phrase is closest to an organizational offshoot?','a branch organization','a completely unrelated rival','an original source with no branches','offshoot can mean a branch derived from a larger group.','meaning'),Q(1,'Why was the network mentioned?','It was the cooperative’s parent organization.','It was an ocean current.','It supplied the city’s electricity.','例句说明合作社从网络发展而来。','context')]);
P('offshore','From off + shore; it means situated in the sea near a coast or, in business, based in a foreign country.',[C('offshore.s1','通用','The company installed offshore wind turbines several kilometers from the coast.','公司在离海岸数公里的海上安装了风力涡轮机。','The company installed offshore wind turbines / several kilometers / from the coast.','offshore.s1 作形容词，表示位于近海或把业务设在国外。','风力机位于离岸的海域。'),C('offshore.s2','通用','The research vessel sailed offshore before lowering its instruments into deeper water.','研究船驶向离岸海域后，才把仪器放入更深的水中。','The research vessel sailed offshore / before lowering its instruments / into deeper water.','offshore.s2 作副词，表示向海上或在海外。','船从岸边驶向外海。')],M('The turbines were offshore because they stood several kilometers inland on a dry plain.','The turbines were offshore because they stood in the sea several kilometers from the coast.','offshore 指离岸或海外，不指内陆旱地。','distinction'),[Q(1,'Where were the wind turbines installed?','In the sea several kilometers from shore.','On a dry inland plain.','Inside the harbor office.','offshore.s1 指海上近岸区域。'),Q(2,'Where did the vessel sail before taking measurements?','Away from the shore into deeper water.','Inland toward the mountains.','Across a city office.','offshore.s2 作副词指驶向海上。'),Q(1,'What does an offshore company often mean?','A company based in another country.','A business located in a school hallway.','A vessel made of oilskin.','offshore 也可指设在海外的公司。','meaning'),Q(1,'Which sentence uses offshore as an adverb?','The boat moved offshore before sunset.','They built an offshore platform.','The offshore company filed a report.','第一句中 offshore 修饰 moved。','grammar')]);
P('offspring','From Old English ofspring, “children, descendants,” from of “away” + springan “spring, arise”; it denotes a person’s children, an animal’s young, or a product of something.',[C('offspring.s1','家庭','The author’s offspring donated her letters to the university archive after her death.','作者去世后，她的子女把她的信件捐给了大学档案馆。','The author’s offspring donated her letters / to the university archive / after her death.','offspring.s1 指某人的孩子或后代。','捐赠者是作者的子女。'),C('offspring.s2','生物','The turtle guarded its offspring until the hatchlings reached the water.','海龟守护着幼崽，直到小海龟抵达水中。','The turtle guarded its offspring / until the hatchlings / reached the water.','offspring.s2 指动物的幼仔。','hatchlings 是海龟的幼体。'),C('offspring.s3','书面','The new community garden was the offspring of a residents’ campaign for unused land.','这座新社区花园是居民争取利用闲置土地的活动所结出的成果。','The new community garden / was the offspring of a residents’ campaign / for unused land.','offspring.s3 可比喻由早先事物发展产生的结果或产物。','花园是居民行动促成的成果。')],M('The biologist called a turtle’s adult parent its offspring and the hatchling its ancestor.','The biologist called the hatchling the turtle’s offspring and the adult its parent.','offspring 指后代或幼体，不是其父母。','distinction'),[Q(1,'Who donated the letters?','The author’s children.','The author’s editor’s children only.','The university’s librarians before the author was born.','offspring.s1 指作者的后代。'),Q(2,'What did the turtle guard?','Its hatchlings.','A group of adult fish.','A city garden.','offspring.s2 指动物幼仔。'),Q(3,'What was the new garden the offspring of?','A residents’ campaign.','A turtle’s nest.','The author’s letters.','offspring.s3 比喻由先前行动产生的结果。'),Q(1,'Can offspring refer to both humans and animals?','Yes; it can mean children or young animals.','No; it only means plants.','No; it only means a business branch.','该词可指人类后代，也可指动物幼体。','meaning')]);
P('oft','From Old English oft, related to often; it is an older or literary adverb meaning frequently or many times.',C('oft.s1','书面','The poet writes of a valley where mist oft gathers before sunrise and lifts by midmorning.','诗人写道，在一个山谷里，薄雾常在日出前聚集，到上午中段才散去。','The poet writes of a valley / where mist oft gathers before sunrise / and lifts by midmorning.','oft 是 often 的较古或文学形式，表示时常。','诗句中 oft 修饰雾聚集的频率。','register'),M('The poet used oft to mean “never,” saying the mist oft gathers even though it has not appeared once.','The poet used oft to mean “frequently,” describing the mist’s repeated appearance.','oft 表示经常，不是从未。','meaning'),[Q(1,'When does mist oft gather in the poem?','Before sunrise.','Only after midnight every decade.','Never.','oft.s1 表示经常发生。'),Q(1,'Which modern word is closest in meaning to oft?','often','off','oddly','oft is an older form of often.','meaning'),Q(1,'What register does oft usually have today?','Literary or old-fashioned.','Technical measurement only.','A plural noun.','oft 常显得古雅或文学化。','register'),Q(1,'What happens to the mist by midmorning?','It lifts.','It becomes a poem.','It moves underground.','例句写雾上午中段散去。','context')]);
P('often','From Old English oft + adverbial -e(n), related to oft; it means on many occasions or, in general statements, in many cases.',[C('often.s1','通用','The ferry often runs late in winter because strong crosswinds slow the crossing.','冬天渡船常常晚点，因为强侧风会减慢航行。','The ferry often runs late in winter / because strong crosswinds / slow the crossing.','often.s1 表示许多次、频繁发生。','often 修饰 runs late，描述反复发生。'),C('often.s2','通用','Small design changes often improve a tool’s comfort even when they do not make it stronger.','即使不让工具更坚固，小小的设计改动往往也能提升使用舒适度。','Small design changes often improve a tool’s comfort / even when they do not make it stronger.','often.s2 可表示在许多情况下往往如此。','这是概括的一般规律，不是特定某一次。')],M('The schedule said the ferry often ran late, but it meant the delay happened only once in ten years.','The schedule said the ferry often ran late during the windy winter months.','often 表示频繁或许多场合，不表示罕见的单次事件。','meaning'),[Q(1,'Why is the ferry often late in winter?','Strong crosswinds slow the crossing.','The boat is always parked inland.','The design changes make the harbor warmer.','often.s1 描述冬季反复出现的延误。'),Q(2,'What do small design changes often improve?','A tool’s comfort.','Its color in every case.','The number of ferry routes.','often.s2 表示许多情况下会改善舒适度。'),Q(1,'Which word is closest to often?','frequently','never','once only','often means on many occasions.','meaning'),Q(1,'In the ferry sentence, what does often modify?','runs late','strong crosswinds','the crossing’s length only','often is an adverb modifying the verb phrase runs late.','grammar')]);
P('oftentimes','From oft + times, with the adverbial -s; it means frequently and is somewhat old-fashioned or especially common in American usage.',C('oftentimes.s1','通用','Oftentimes, the first frost arrives before the mountain road is fully cleared of fallen leaves.','山路上的落叶还没清理干净，初霜往往就先到了。','Oftentimes / the first frost arrives / before the mountain road is fully cleared / of fallen leaves.','oftentimes 表示经常，语气略显古风或带美式色彩。','句首副词概括常见的先后情形。','register'),M('The guide used oftentimes to mean “just once,” although she described a recurring seasonal pattern.','The guide used oftentimes to mean “frequently,” describing a recurring seasonal pattern.','oftentimes 表示常常，不是只发生一次。','meaning'),[Q(1,'What tends to arrive before the road is cleared?','The first frost.','The spring flowers.','The summer ferry.','oftentimes.s1 表示这种情况常发生。'),Q(1,'Which word can replace oftentimes in most contexts?','often','never','tomorrow','oftentimes means frequently.','meaning'),Q(1,'What stylistic flavor may oftentimes have?','Slightly old-fashioned or American.','Strictly scientific and numeric.','Always rude or insulting.','该词常带古风或美式色彩。','register'),Q(1,'What does the sentence describe?','A recurring seasonal pattern.','A single frost from centuries ago.','A ferry crossing in summer.','常见的季节规律由 oftentimes 引出。','context')]);
P('ogre','From French ogre, probably influenced by Latin Orcus “underworld”; an ogre is a frightening imaginary monster, or figuratively a cruel, terrifying person.',[C('ogre.s1','文学','In the folktale, the ogre guarded the bridge and demanded a riddle from everyone who tried to cross.','在民间故事里，食人魔守着桥，要求每个想过桥的人回答一个谜语。','In the folktale / the ogre guarded the bridge / and demanded a riddle / from everyone who tried to cross.','ogre.s1 指故事中的可怕怪物，也可比喻令人害怕的人。','怪物看守桥并拦住旅人。')],M('The story called the gentle bridge guard an ogre although he welcomed every traveler and threatened no one.','The story called the frightening monster who blocked travelers an ogre.','ogre 通常指可怕的怪物或凶恶的人，不是友善的守桥人。','distinction'),[Q(1,'What did the ogre demand from travelers?','A riddle.','A hotel room key.','A map of the Pacific.','ogre.s1 是故事中的可怕怪物。'),Q(1,'Which character could be called an ogre figuratively?','A cruel boss who frightens everyone.','A kind neighbor who helps freely.','A quiet child reading a poem.','比喻义可形容令人害怕或残酷的人。','meaning'),Q(1,'Where did the ogre guard the bridge?','In a folktale.','At a real ferry terminal in the example.','Inside a university archive.','例句设定在民间故事中。','context'),Q(1,'What is an ogre most likely to be in a fairy tale?','A frightening monster.','A polite officeholder.','An oceanographer.','ogre 通常指童话怪物。','meaning')]);
P('ohp','An initialism of overhead projector; OHP names a device that projects an image from a transparent sheet onto a screen or wall.',C('ohp.s1','教育','The teacher placed a transparent diagram on the OHP and adjusted the focus so students at the back could read it.','老师把透明图表放在高射投影仪上，并调好焦距，让后排学生也看得清。','The teacher placed a transparent diagram on the OHP / and adjusted the focus / so students at the back could read it.','ohp/OHP 是 overhead projector 的缩写，指高射投影仪。','透明片上的图像被投射到远处屏幕。','capitalization'),M('The classroom note called a device that projected transparent slides an OHP but expanded the letters as “ordinary hand paper.”','The classroom note expanded OHP as “overhead projector,” the device used to project transparent slides.','OHP 是 overhead projector 的首字母缩写。','word-formation'),[Q(1,'What did the teacher place on the OHP?','A transparent diagram.','A metal spoon.','An ocean water sample.','ohp.s1 指投影仪，透明图表放在其载物台上。'),Q(1,'What does OHP stand for?','Overhead projector.','Official harbor police.','Oddly heated paper.','OHP is short for overhead projector.','word-formation'),Q(1,'Why did the teacher adjust the focus?','So students at the back could read the projected image.','To make the paper disappear.','To change the diagram into a photograph.','调焦让后排看清投影。','context'),Q(1,'How is OHP normally written as an initialism?','OHP','ohp’s as a verb','O.H.P.S. only','The source abbreviation is capitalized as OHP.','capitalization')]);
P('oil','From Old English æle, from Latin oleum “olive oil,” from Greek elaion; the noun can mean plant/animal fat, petroleum, or oil paint, and the verb means to apply lubricant.',[C('oil.s1','饮食','She brushed olive oil over the vegetables before roasting them with garlic and herbs.','她在蔬菜上刷了一层橄榄油，再与大蒜和香草一起烤。','She brushed olive oil / over the vegetables / before roasting them / with garlic and herbs.','oil.s1 指烹饪用的植物或动物油。','橄榄油涂在蔬菜上用于烹饪。'),C('oil.s2','能源','The tanker carried crude oil from the offshore field to a refinery on the coast.','油轮把海上油田的原油运到海岸边的炼油厂。','The tanker carried crude oil / from the offshore field / to a refinery / on the coast.','oil.s2 指石油或由石油制成的燃料。','原油由油田运往炼油厂。'),C('oil.s3','艺术','The painter layered blue oil on the canvas and waited for the thick pigment to dry.','画家在画布上层层涂上蓝色油彩，并等浓稠的颜料干燥。','The painter layered blue oil / on the canvas / and waited / for the thick pigment to dry.','oil.s3 指油画颜料或油彩。','颜料涂在画布上并需要干燥。'),C('oil.s4','机械','The mechanic oiled the hinge to stop the workshop door from squeaking.','机械师给铰链上了油，避免工坊的门吱吱作响。','The mechanic oiled the hinge / to stop the workshop door / from squeaking.','oil.s4 作动词，表示给机器或表面涂油润滑。','润滑铰链减少摩擦与异响。')],M('The mechanic oiled the hinge with dry sand, which increased friction and made the squeak louder.','The mechanic oiled the hinge with lubricant to reduce friction and quiet the squeak.','上油润滑可减少摩擦；干砂会增加摩擦。','word-choice'),[Q(1,'What did she brush over the vegetables?','Olive oil.','Crude petroleum.','Blue paint.','oil.s1 是烹饪用油。'),Q(2,'Where was the crude oil going?','To a coastal refinery.','To a painter’s canvas.','To a hinge as dry sand.','oil.s2 指原油。','context'),Q(3,'What did the painter apply to the canvas?','Blue oil paint.','Cooking garlic.','A lubricant for a door hinge.','oil.s3 是油画颜料。'),Q(4,'Why did the mechanic oil the hinge?','To stop it squeaking.','To make the door heavier.','To transport it to a refinery.','oil.s4 指给铰链涂润滑油。','context')]);
P('oilskin','From oil + skin; it originally referred to cloth waterproofed with oil and can mean that material or a sailor’s coat made from it.',C('oilskin.s1','生活','The deckhand wore an oilskin during the squall because the treated cloth shed spray from the waves.','暴风雨来时，甲板水手穿上油布雨衣，因为经过处理的布料能挡住浪花。','The deckhand wore an oilskin / during the squall / because the treated cloth / shed spray from the waves.','oilskin 指经油处理的防水布，也可指用这种布做的水手外衣。','外衣抵挡海浪溅起的水。','word-formation'),M('The sailor’s oilskin soaked up seawater immediately because it was untreated, absorbent cotton.','The sailor’s oilskin shed seawater because the cloth had been treated to resist water.','油布经处理后防水；未处理吸水棉布不符合定义。','distinction'),[Q(1,'Why did the deckhand wear an oilskin?','It shed spray from the waves.','It absorbed seawater like a towel.','It measured the tide.','oilskin.s1 指防水的油布或雨衣。'),Q(1,'What was treated to resist water?','The cloth.','The waves.','The ship’s engine.','油处理让布料能挡水。','context'),Q(1,'Which item could be made of oilskin?','A sailor’s waterproof coat.','A transparent projector slide.','A glass laboratory beaker.','水手外衣可用防水油布制成。','meaning'),Q(1,'How is oilskin formed?','oil + skin','oil + plural -s','off + skin','It is a compound naming oil-treated cloth.','word-formation')]);
P('oily','From oil + -y; it means containing or covered with oil, and figuratively can describe a too-smooth, flattering manner.',[C('oily.s1','通用','The pan remained oily after washing, so she rinsed it again with hot water and soap.','锅洗过后仍油腻，所以她用热水和肥皂又冲洗了一次。','The pan remained oily / after washing / so she rinsed it again / with hot water and soap.','oily.s1 表示含油或表面沾油。','锅面残留油脂。'),C('oily.s2','通用','The salesman’s oily compliments made the cautious buyer wonder what he was trying to hide.','推销员油滑的奉承让谨慎的买家怀疑他想隐瞒什么。','The salesman’s oily compliments / made the cautious buyer wonder / what he was trying to hide.','oily.s2 可比喻态度过分圆滑、爱奉承。','奉承听起来虚伪而刻意。')],M('The pan was oily because every trace of grease had been completely removed.','The pan was no longer oily after the grease had been removed.','oily 表示沾油，与完全去油相反。','distinction'),[Q(1,'Why did she rinse the pan again?','It still had oil on it.','It was already completely dry and clean.','It was made of glass.','oily.s1 表示表面有油。'),Q(2,'What did the buyer think about the salesman’s compliments?','They sounded excessively flattering and suspicious.','They were entirely neutral and factual.','They were instructions about cooking oil.','oily.s2 指油滑奉承的态度。'),Q(1,'Which object is oily?','A greasy pan.','A dry towel with no residue.','A polished empty glass.','含油或沾油的东西是 oily。','meaning'),Q(2,'Which behavior could be described as oily?','Overly smooth praise meant to win favor.','A straightforward safety warning.','A quiet factual answer.','比喻义形容过分圆滑、奉承。','meaning')]);
P('ointment','From Old French oignement, from Latin unguentum “salve,” from unguere “anoint”; it is a soft preparation applied to the skin.',C('ointment.s1','医学','She applied a thin layer of ointment to the dry patch and followed the pharmacist’s instructions.','她在干燥的皮肤处薄薄涂了一层软膏，并遵照药剂师的说明。','She applied a thin layer of ointment / to the dry patch / and followed the pharmacist’s instructions.','ointment 指供外用的半固体药膏或护肤品。','软膏涂在皮肤表面。'),M('The label instructed patients to swallow the ointment as a liquid drink for internal use.','The label instructed patients to apply the ointment to the skin as directed.','ointment 通常是外用软膏，不应误作口服液体。','usage'),[Q(1,'Where did she apply the ointment?','On a dry patch of skin.','In a glass of water.','Inside a car engine.','ointment.s1 是外用制剂。'),Q(1,'How much ointment did she use?','A thin layer.','A whole bottle as a drink.','A spoonful poured into the engine.','例句说明她薄涂软膏。','context'),Q(1,'What is an ointment’s usual form?','A soft, semi-solid preparation.','A hard metal tool.','A gas used for fuel.','软膏通常是半固体。','meaning'),Q(1,'Which verb naturally collocates with ointment?','apply','sail','officiate','ointment is applied to the skin.','collocation')]);
P('OK','A colloquial spelling/initialism commonly explained as “oll korrect,” a humorous 1839 misspelling of “all correct”; it developed adjective, adverb, and noun uses.',[C('OK.s1','口语','The bicycle is OK after the mechanic tightened the loose brake cable and tested it on the lane.','机械师拧紧松动的刹车线并在小路上测试后，自行车状况良好。','The bicycle is OK / after the mechanic tightened the loose brake cable / and tested it on the lane.','OK.s1 作形容词，表示还好、可以或被允许。','维修后车况令人满意。'),C('OK.s2','口语','“We’ll meet outside the station at six.” “OK,” Lena replied, saving the time in her calendar.','“我们六点在车站外见。”“好。”莉娜回答，并把时间记进日历。','“We’ll meet outside the station at six.” / “OK,” Lena replied / saving the time in her calendar.','OK.s2 作副词或感叹回应，表示同意或继续。','答复表示接受约定。'),C('OK.s3','口语','The contractor waited for the client’s OK before ordering the custom windows.','承包商等客户批准后才订购定制窗户。','The contractor waited for the client’s OK / before ordering / the custom windows.','OK.s3 作名词，指批准或同意。','客户的许可是下订单的前提。')],M('The contractor ordered the windows before receiving the client’s OK and later claimed the client had approved the order.','The contractor waited for the client’s OK before placing the custom order.','名词 OK 表示批准；未获批准就订购与等待许可相矛盾。','context'),[Q(1,'How was the bicycle after repair?','In satisfactory condition.','Still unsafe and broken.','A type of window order.','OK.s1 表示状况尚可。'),Q(2,'What did Lena mean by “OK”?','She agreed to the meeting plan.','She rejected the time.','She asked for a new bicycle.','OK.s2 用作回应表示同意。'),Q(3,'What was the contractor waiting for?','The client’s approval.','A train ticket.','A brake cable.','OK.s3 是批准或许可。'),Q(1,'Which phrase means the bicycle was acceptable?','The bicycle is OK.','The client gave the OK.','“OK,” Lena replied.','第一句中的 OK 作形容词。','grammar')]);
P('okay','Variant spelling of OK, from the same colloquial expression commonly explained as “oll korrect”; it functions as adjective, adverb, interjection, verb, and noun.',[C('okay.s1','口语','The soup is okay after a little more salt, although it is not the best dish on the menu.','再加一点盐后，这汤还可以，虽然不是菜单上最好的菜。','The soup is okay / after a little more salt / although it is not the best dish / on the menu.','okay.s1 作形容词，表示可接受、状况良好或获准。','味道可接受但不算最好。'),C('okay.s2','口语','The repaired radio works okay, but the volume control still crackles at its highest setting.','修好的收音机运行得还行，但音量调到最大时控制钮仍会发出噼啪声。','The repaired radio works okay / but the volume control still crackles / at its highest setting.','okay.s2 作副词，表示尚可、过得去。','works 后的副词描述运行情况。'),C('okay.s3','口语','“I’ll send the revised map tonight.” “Okay,” the surveyor said, closing the folder.','“我今晚把修订地图发给你。”“好。”测绘员说着合上文件夹。','“I’ll send the revised map tonight.” / “Okay,” the surveyor said / closing the folder.','okay.s3 作感叹词，表示同意或引出下一步。','回答表示接受对方安排。'),C('okay.s4','口语','The director will okay the final budget once the department heads confirm their estimates.','部门负责人确认估算后，主任会批准最终预算。','The director will okay the final budget / once the department heads / confirm their estimates.','okay.s4 作动词，表示批准计划或提案。','主任对预算给予批准。'),C('okay.s5','口语','We cannot print the poster until we get the designer’s okay on the revised colors.','在拿到设计师对修订配色的许可前，我们不能印海报。','We cannot print the poster / until we get the designer’s okay / on the revised colors.','okay.s5 作名词，表示许可或同意。','名词 okay 是印刷前所需的许可。')],M('The team printed the poster before asking the designer and then said it still needed the designer’s okay.','The team waited for the designer’s okay before printing the poster.','已印刷后才说仍需事先许可，前后矛盾。','context'),[Q(1,'How good was the soup?','Acceptable, though not the menu’s best.','Perfect and unquestionably the best.','Too dangerous to taste.','okay.s1 表示可以、尚可。'),Q(2,'How does the repaired radio work?','Adequately, with a remaining crackle at high volume.','Perfectly with no remaining problem.','Not at all because it was never repaired.','okay.s2 作副词表示运行得还行。'),Q(3,'What did the surveyor’s “Okay” signal?','Agreement with the plan.','A refusal to receive the map.','Approval of a budget by the director.','okay.s3 是表示同意的回应。'),Q(4,'Which sentence uses okay as a verb?','The director will okay the budget.','The budget is okay.','We need the director’s okay.','will okay 后接宾语，表示批准。','grammar')]);
P('old','From Old English ald, from Proto-Germanic *althaz; senses include advanced in age, not new or used for a long time, a specified age, and former or previous.',[C('old.s1','通用','The old lighthouse keeper still climbed the stairs each morning, though he used the handrail carefully.','年迈的灯塔看守仍每天早上爬楼梯，尽管他会小心扶着栏杆。','The old lighthouse keeper / still climbed the stairs / each morning / though he used the handrail carefully.','old.s1 指年纪大、年老的。','人物年长，因此小心使用扶手。'),C('old.s2','通用','They replaced the old carpet after years of wear had left a bare patch beside the doorway.','地毯使用多年、门口旁磨出一块秃斑后，他们把旧地毯换掉了。','They replaced the old carpet / after years of wear / had left a bare patch / beside the doorway.','old.s2 指存在或使用已久、不再新的。','多年磨损说明地毯已经用旧。'),C('old.s3','家庭','Their daughter is twelve years old and will start secondary school in September.','他们的女儿十二岁，九月将升入中学。','Their daughter is twelve years old / and will start secondary school / in September.','old.s3 用在数字后表示年龄。','twelve years old 表示十二岁。'),C('old.s4','通用','An old colleague from the newspaper visited the newsroom during her trip back to town.','一位以前在报社共事的同事回城旅行时探访了编辑部。','An old colleague from the newspaper / visited the newsroom / during her trip back to town.','old.s4 可指以前的、过去的关系或事物。','old colleague 指过去共事的同事，不强调年龄。')],M('The twelve-year-old daughter was described as twelve years old in the sentence, but the draft said she was twelve months old.','Their daughter is twelve years old and will start secondary school in September.','years old 表示以年计的年龄，months old 会改变年龄含义。','number'),[Q(1,'Why did the keeper use the handrail?','He was elderly.','The lighthouse was brand-new.','He was twelve years old.','old.s1 表示年迈。'),Q(2,'Why was the carpet replaced?','Years of use had worn it.','It had never been used.','It belonged to a former colleague.','old.s2 指用旧、存在已久。'),Q(3,'How old is the daughter?','Twelve years old.','Twelve months old.','Twenty years old.','old.s3 用数字表达年龄。','number'),Q(4,'What does old colleague mean here?','A colleague from the past.','An elderly person who is currently her supervisor.','A new hire.','old.s4 表示以前的同事关系。','distinction')]);
P('old hand','An idiom formed from old + hand; it means a person with long experience and skill in a particular activity.',C('old hand.s1','职业','As an old hand at flood response, Marta organized the sandbag line before the first heavy rain arrived.','作为防洪应急的老手，玛尔塔在第一场大雨来临前就组织好了沙袋队伍。','As an old hand at flood response / Marta organized the sandbag line / before the first heavy rain arrived.','old hand 指在某项活动中经验丰富、熟练的人。','她凭经验提前组织应急工作。'),M('The report called Marta an old hand even though she had never taken part in flood response and needed every step explained.','The report called Marta an old hand because years of flood-response work had made her experienced.','old hand 指有丰富经验的人，不适合毫无经验的新手。','distinction'),[Q(1,'What activity was Marta experienced in?','Flood response.','Marine painting.','Hotel accounting.','old hand.s1 指在某项活动中的熟手。'),Q(1,'What did she organize before the rain?','A sandbag line.','A poetry reading.','An oil tanker.','例句说明她提前安排防洪工作。','context'),Q(1,'Which person is an old hand at cooking?','A chef who has cooked professionally for decades.','A beginner who has never used a stove.','A visitor who only reads menus.','熟练且有经验的人是 old hand。','meaning'),Q(1,'Does old hand refer to a literal aged hand?','No; it is an idiom for an experienced person.','Yes; it means a hand with wrinkles only.','Yes; it means an old glove.','该短语是习语，指经验丰富的人。','distinction')]);
P('old-fashioned','From old + fashioned, first referring to a style made in an earlier fashion; it can describe a dated design or a person who prefers traditional ways.',[C('old-fashioned.s1','通用','The hotel replaced its old-fashioned key system with electronic cards that guests could deactivate from their phones.','酒店用电子房卡取代了老式钥匙系统，客人还可以用手机停用房卡。','The hotel replaced its old-fashioned key system / with electronic cards / that guests could deactivate / from their phones.','old-fashioned.s1 指不再时新的样式或方法。','机械钥匙系统被更新的电子房卡替代。'),C('old-fashioned.s2','社会','Her old-fashioned parents insisted that guests be greeted at the door and offered tea before dinner.','她的父母观念传统，坚持要在门口迎接客人，并在晚饭前请客人喝茶。','Her old-fashioned parents insisted / that guests be greeted at the door / and offered tea / before dinner.','old-fashioned.s2 可形容偏爱过去礼节或观念的人。','父母坚持旧式待客礼节。')],M('The hotel called its new phone-controlled card system old-fashioned even though it had replaced the obsolete metal keys.','The hotel called its obsolete metal-key system old-fashioned and replaced it with phone-controlled cards.','已被现代技术取代的旧系统才符合此处 old-fashioned。','distinction'),[Q(1,'What did the hotel replace?','An outdated key system.','A new phone app.','The guests’ dinner table.','old-fashioned.s1 指过时的系统。'),Q(2,'What did the parents insist on?','Traditional ways of welcoming guests.','Using only electronic key cards.','Skipping all greetings.','old-fashioned.s2 指坚持旧式礼仪。'),Q(1,'Which object is old-fashioned in this context?','A mechanical key system replaced by modern cards.','A newly installed digital lock.','A current phone-controlled access app.','传统钥匙系统相对新式电子卡显得过时。','distinction'),Q(2,'Does old-fashioned always criticize a person?','No; it can describe traditional preferences without a strong insult.','Yes; it always means criminal.','No; it only means elderly.','描述传统观念时语气未必强烈贬义。','register')]);
P('older','From old + comparative -er; older is the comparative form used to say someone or something has greater age than another.',C('older.s1','家庭','My older sister taught me to ride a bicycle before I started school.','我上学前，姐姐教会了我骑自行车。','My older sister / taught me to ride a bicycle / before I started school.','older.s1 是 old 的比较级，表示年龄较大或较旧。','older sister 与说话者相比年长。','word-formation'),M('Nina is the older of the two sisters even though she was born three years after her sibling.','Nina is the younger of the two sisters because she was born three years after her sibling.','出生更晚的姐妹年龄更小，不是 older。','distinction'),[Q(1,'Who taught the speaker to ride?','The speaker’s older sister.','A younger sibling born later.','A former newspaper colleague.','older.s1 表示姐姐比说话者年长。'),Q(1,'What does older compare?','Age or length of existence.','The number of sides in a shape.','The loudness of a radio.','older 是 old 的比较级。','meaning'),Q(1,'Which form is comparative?','older','oldest','oldly','older adds comparative -er.','word-formation'),Q(1,'If Ava is older than Ben, who has lived longer?','Ava.','Ben.','They must be twins.','older than 表示年龄更大。','grammar')]);
P('olfactory','From Latin olfactorius “of smelling,” from olfacere “to smell”; it is chiefly an adjective for the sense or organs of smell, and can be a noun for a smell organ.',[C('olfactory.s1','医学','The neurologist tested the patient’s olfactory response by asking her to identify familiar scents with her eyes closed.','神经科医生让患者闭上眼睛辨认熟悉的气味，以测试她的嗅觉反应。','The neurologist tested the patient’s olfactory response / by asking her / to identify familiar scents / with her eyes closed.','olfactory.s1 作形容词，表示嗅觉的或与嗅觉器官有关的。','测试通过辨认气味评估嗅觉。'),C('olfactory.s2','生物','In many animals, an olfactory is a specialized organ that detects airborne chemicals.','在许多动物身上，嗅觉器官是探测空气中化学物质的专门结构。','In many animals / an olfactory is a specialized organ / that detects airborne chemicals.','olfactory.s2 作名词，指嗅觉器官。','名词义说明负责检测气味的器官。')],M('The clinic called a visual color chart an olfactory test even though the patient did not smell anything.','The clinic called the scent-identification task an olfactory test.','olfactory 指嗅觉，单纯看颜色的测试不是嗅觉测试。','distinction'),[Q(1,'What did the neurologist test?','The patient’s sense of smell.','Her ability to hear music.','Her balance on a bicycle.','olfactory.s1 与嗅觉有关。'),Q(2,'What does an olfactory mean as a noun in the source?','A specialized organ for detecting smells.','A scentless chart.','A type of ocean current.','olfactory.s2 指嗅觉器官。'),Q(1,'Which is an olfactory response?','Recognizing the smell of cinnamon.','Recognizing a red circle by sight.','Hearing a bell ring.','辨认气味是嗅觉反应。','meaning'),Q(2,'What do olfactory organs detect?','Airborne chemicals.','The age of a person.','The number of seats in a theater.','嗅觉器官探测空气中的化学物质。','context')]);
P('oligopoly','From Greek oligoi “few” + polein “to sell,” by analogy with monopoly; it names a market dominated by a small number of firms, each able to influence price or supply.',C('oligopoly.s1','经济','Three airlines control most routes between the islands, giving the market the structure of an oligopoly.','三家航空公司控制了岛屿间的大多数航线，使这个市场呈现寡头垄断结构。','Three airlines control most routes between the islands / giving the market / the structure of an oligopoly.','oligopoly 指由少数企业主导、各家都能影响价格或供应的市场结构。','市场份额集中在三家航空公司手中。'),M('The report called the market an oligopoly even though thousands of tiny sellers each had no influence on price.','The report called the market an oligopoly because a few large airlines controlled most routes and could influence prices.','oligopoly 的关键是少数企业集中控制市场并能影响价格。','distinction'),[Q(1,'How many airlines controlled most island routes?','Three.','Thousands.','One hundred unrelated airlines.','oligopoly.s1 是少数企业控制市场的结构。','number'),Q(1,'Why is the airline market an oligopoly?','A few firms control much of the market and can influence it.','One seller has exclusive control.','Every seller is too small to affect anything.','寡头市场由少数有影响力的企业主导。'),Q(1,'Which market could be an oligopoly?','A few firms dominate nearly all mobile service.','Thousands of farms sell identical produce with no market power.','One shop sells a unique handmade cup.','少数企业主导行业符合 oligopoly。','context'),Q(1,'What does the element oligo- mean?','Few.','Many.','One hundred.','Greek oligoi means “few.”','word-formation')]);

})();
